window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p52147c311e"]={"id":"p52147c311e","name":"2025年湖北省公务员录用考试《行测》题（网友回忆版）","year":2025,"region":"湖北","count":78,"types":{"新思想":10,"时事政治":3,"逻辑填空":15,"片段阅读":13,"语句表达":2,"图形推理":5,"定义判断":8,"逻辑判断":9,"类比推理":13},"modules":["政治理论","言语理解与表达","判断推理"],"questions":[{"qid":"13504477","no":1,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，现代化产业体系是现代化国家的物质技术基础，关于现代化产业体系建设，下列表述正确的有几项？<br>①坚持把发展经济的着力点放在国有企业上<br>②推动制造业高端化、智能化、绿色化发展<br>③推动战略性新兴产业融合集群发展<br>④推动现代服务业同先进制造业、现代农业深度融合<br>⑤优化基础设施布局、结构、功能和系统集成，构建现代化基础设施体系</p>","options":[{"k":"A","t":"5项"},{"k":"B","t":"4项"},{"k":"C","t":"3项"},{"k":"D","t":"2项"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>②③④⑤正确，①错误，二十大报告在“四、加快构建新发展格局，着力推动高质量发展”中指出“（二）建设现代化产业体系。坚持把发展经济的着力点放在实体经济上，推进新型工业化，加快建设制造强国、质量强国、航天强国、交通强国、网络强国、数字中国。实施产业基础再造工程和重大技术装备攻关工程，支持专精特新企业发展，推动制造业高端化、智能化、绿色化发展······推动战略性新兴产业融合集群发展，构建新一代信息技术、人工智能、生物技术、新能源、新材料、高端装备、绿色环保等一批新的增长引擎。构建优质高效的服务业新体系，推动现代服务业同先进制造业、现代农业深度融合······优化基础设施布局、结构、功能和系统集成，构建现代化基础设施体系。”故“发展经济的着力点放在国有企业上”说法错误。<br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"p52147c311e"},{"qid":"13504664","no":2,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，我们要坚定不移走中国特色社会主义政治发展道路，坚持和完善我国根本政治制度、基本政治制度、重要政治制度，不断健全人民当家作主制度体系。以下哪项是我国根本政治制度：</p>","options":[{"k":"A","t":"党领导的多党合作和政治协商制度"},{"k":"B","t":"人民代表大会制度"},{"k":"C","t":"民族区域自治制度"},{"k":"D","t":"基层群众自治制度"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>B项正确，A、C、D三项错误，坚持中国特色社会主义制度，就是要坚持把根本政治制度、基本政治制度、基本经济制度和其他各方面机制体制有机结合起来。我国的根本政治制度是人民代表大会制度；我国的基本政治制度是中国共产党领导的多党合作和政治协商制度、民族区域自治制度以及基层群众自治制度。<br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"p52147c311e"},{"qid":"13504475","no":3,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，要坚持城乡融合发展，畅通城乡要素流动。关于城乡融合发展，下列说法正确的有几项？<br>①城乡融合发展是中国式现代化的必然要求<br>②推进以乡镇为重要载体的新型城镇化建设，发展各具特色的乡镇经济<br>③发展新型农村集体经济，构建产权明晰、分配合理的运行机制<br>④完善覆盖农村人口的常态化防止返贫致贫机制<br>⑤允许农户合法拥有的住房通过出租、入股、合作等方式盘活利用</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过《中共中央关于进一步全面深化改革 推进中国式现代化的决定》（以下简称《决定》）。<br>①正确，《决定》在“六、完善城乡融合发展体制机制”部分指出：“城乡融合发展是中国式现代化的必然要求。必须统筹新型工业化、新型城镇化和乡村全面振兴，全面提高城乡规划、建设、治理融合水平······”<br>②错误，2024年11月4日至6日，习近平总书记在湖北考察时指出，推进以县城为重要载体的新型城镇化建设，发展各具特色的县域经济。故“乡镇经济”说法错误。<br>③正确，《决定》在“六、完善城乡融合发展体制机制”部分指出：“（21）巩固和完善农村基本经营制度······发展新型农村集体经济，构建产权明晰、分配合理的运行机制，赋予农民更加充分的财产权益。”<br>④正确，《决定》在“六、完善城乡融合发展体制机制”部分指出：“（22）完善强农惠农富农支持制度······完善覆盖农村人口的常态化防止返贫致贫机制，建立农村低收入人口和欠发达地区分层分类帮扶制度。”<br>⑤正确，《决定》在“六、完善城乡融合发展体制机制”部分指出：“（23）深化土地制度改革······允许农户合法拥有的住房通过出租、入股、合作等方式盘活利用。”<br>故正确的有①③④⑤，共4项。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"p52147c311e"},{"qid":"13504476","no":4,"type":"时事政治","module":"政治理论","stem":"<p>习近平总书记指出，人心是最大的政治，统一战线是凝聚人心、汇聚力量的强大法宝，关于统一战线，下列表述正确的是：<br>①统战工作的本质要求是大团结大联合，解决的就是人心和力量问题<br>②统一战线是党领导的统一战线，其最鲜明的特征是坚持以人民为中心<br>③发展壮大爱国爱港爱澳力量，增强港澳同胞的爱国精神，形成更广泛的国内外支持“一国两制”的统一战线<br>④关键是要坚持求同存异，发扬“团结一批评一团结”的优良传统，在尊重多样性中寻求一致性</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，在2022年7月29日至30日召开的中央统战工作会议上，习近平总书记指出，统一战线是党克敌制胜、执政兴国的重要法宝，是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝，必须长期坚持······统战工作的本质要求是大团结大联合，解决的就是人心和力量问题······<br>②错误，在2022年7月29日至30日召开的中央统战工作会议上，习近平总书记指出，加强新时代统一战线工作，根本在于坚持党的领导。中国共产党领导是统一战线最鲜明的特征，坚持党的领导是统一战线最根本、最核心的问题。故“最鲜明的特征是坚持以人民为中心”说法错误。<br>③正确，二十大报告在“十三、坚持和完善‘一国两制’，推进祖国统一”中指出：“‘一国两制’是中国特色社会主义的伟大创举，是香港、澳门回归后保持长期繁荣稳定的最佳制度安排，必须长期坚持······发展壮大爱国爱港爱澳力量，增强港澳同胞的爱国精神，形成更广泛的国内外支持‘一国两制’的统一战线······”<br>④正确，《习近平总书记关于做好新时代党的统一战线工作的重要思想学习读本》中强调：“‘团结——批评——团结’是我们党处理党内矛盾和人民内部矛盾的基本原则和基本方式，也是党领导的统一战线的优良传统······习近平总书记指出：‘关键是要坚持求同存异，发扬‘团结——批评——团结’的优良传统，在尊重多样性中寻求一致性，找到最大公约数、画出最大同心圆。’”<br>故正确的是①③④。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"p52147c311e"},{"qid":"13504496","no":5,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，纵观人类历史，教育兴则国家兴，教育强则国家强，世界强国无一不是教育强国，教育始终是强国兴起的关键因素。关于建设教育强国，下列表述正确的有几项？<br>①要坚持不懈用新时代中国特色社会主义思想铸魂育人，着力加强社会主义核心价值观教育<br>②必须以坚持党对教育事业的全面领导为根本保证<br>③坚持把高速高效发展作为各级各类教育的生命线<br>④建设教育强国，龙头是义务教育</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>2023年5月29日，中共中央政治局就建设教育强国进行第五次集体学习，中共中央总书记习近平主持学习会议并发表讲话。<br>①正确，习近平总书记指出，要坚持不懈用新时代中国特色社会主义思想铸魂育人，着力加强社会主义核心价值观教育，引导学生树立坚定的理想信念，永远听党话、跟党走，矢志奉献国家和人民。<br>②正确，习近平总书记强调，我们要建设的教育强国，是中国特色社会主义教育强国，必须以坚持党对教育事业的全面领导为根本保证······<br>③错误，习近平总书记强调，要坚持把高质量发展作为各级各类教育的生命线，加快建设高质量教育体系。建设教育强国，基点在基础教育······故“高速高效发展”说法错误。<br>④错误，习近平总书记强调，建设教育强国，龙头是高等教育。要把加快建设中国特色、世界一流的大学和优势学科作为重中之重，大力加强基础学科、新兴学科、交叉学科建设······故“龙头是义务教育”说法错误。<br>故表述正确的是①②，共2项。<br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":4,"pid":"p52147c311e"},{"qid":"13504416","no":6,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届三中全会提出，高水平社会主义市场经济体制是中国式现代化的重要保障，关于构建高水平社会主义市场经济体制，下列举措不恰当的是：</p>","options":[{"k":"A","t":"完善市场准入制度，优化新业态新领域市场准入环境"},{"k":"B","t":"推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通"},{"k":"C","t":"加强财政政策和货币政策协调配合，着力扩大内需，增强消费对优化供给结构的基础性作用"},{"k":"D","t":"建立国有企业履行战略使命评价制度，完善国有企业分类考核评价体系，开展国有经济增加值核算"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>A项正确，《中共中央关于进一步全面深化改革 推进中国式现代化的决定》在“二、构建高水平社会主义市场经济体制”部分指出：“（7）完善市场经济基础制度······完善市场准入制度，优化新业态新领域市场准入环境······”<br>B项正确，《中共中央关于进一步全面深化改革 推进中国式现代化的决定》在“二、构建高水平社会主义市场经济体制”部分指出：“（6）构建全国统一大市场。推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通。加强公平竞争审查刚性约束，强化反垄断和反不正当竞争······”<br>C项错误，二十大报告在“四、加快构建新发展格局，着力推动高质量发展”部分指出：“（一）构建高水平社会主义市场经济体制······健全宏观经济治理体系，发挥国家发展规划的战略导向作用，加强财政政策和货币政策协调配合，着力扩大内需，增强消费对经济发展的基础性作用和投资对优化供给结构的关键作用。”故“消费对优化供给结构的基础性作用”的表述错误。<br>D项正确，《中共中央关于进一步全面深化改革 推进中国式现代化的决定》在“二、构建高水平社会主义市场经济体制”部分指出：“（5）坚持和落实‘两个毫不动摇’······建立国有企业履行战略使命评价制度，完善国有企业分类考核评价体系，开展国有经济增加值核算。推进能源、铁路、电信、水利、公用事业等行业自然垄断环节独立运营和竞争性环节市场化改革，健全监管体制机制。”<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":5,"pid":"p52147c311e"},{"qid":"13504665","no":7,"type":"新思想","module":"政治理论","stem":"<p>坚定理想信念，坚守共产党人精神追求，始终是共产党人安身立命的根本。关于推动理想信念教育常态化制度化，下列表述不恰当的是：</p>","options":[{"k":"A","t":"形成网上思想道德教育统一化、标准化实施机制"},{"k":"B","t":"建立健全道德领域突出问题协同治理机制，完善“扫黄打非”长效机制"},{"k":"C","t":"健全诚信建设长效机制，教育引导全社会自觉遵守法律，遵循公序良俗"},{"k":"D","t":"优化英模人物宣传学习机制，创新爱国主义教育和各类群众性主题活动组织机制"}],"answer":"A","multi":false,"explanation":"<p>本题考查理论与政策。<br>A项错误，B、C、D三项正确，《中共中央关于进一步全面深化改革 推进中国式现代化的决定》中“十、深化文化体制机制改革”部分的“（38）完善意识形态工作责任制”中指出：“推动理想信念教育常态化制度化。完善培育和践行社会主义核心价值观制度机制。改进创新文明培育、文明实践、文明创建工作机制。实施文明乡风建设工程。优化英模人物宣传学习机制，创新爱国主义教育和各类群众性主题活动组织机制，推动全社会崇尚英雄、缅怀先烈、争做先锋。构建中华传统美德传承体系，健全社会公德、职业道德、家庭美德、个人品德建设体制机制，健全诚信建设长效机制，教育引导全社会自觉遵守法律、遵循公序良俗，坚决反对拜金主义、享乐主义、极端个人主义和历史虚无主义。形成网上思想道德教育分众化、精准化实施机制。建立健全道德领域突出问题协同治理机制，完善‘扫黄打非’长效机制。”故“统一化、标准化实施机制”说法错误，应为“分众化、精准化实施机制”。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":6,"pid":"p52147c311e"},{"qid":"13504418","no":8,"type":"新思想","module":"政治理论","stem":"<p>统一开放的交通运输市场是有效衔接供需、促进国民经济循环畅通的重要基础，关于加快建设统一开放的交通运输市场，下列举措不恰当的是：</p>","options":[{"k":"A","t":"建立交通运输装备能源清洁替代机制，保障规划实施全类运输工具应用新能源、清洁能源"},{"k":"B","t":"对交通运输领域招标投标、政府采购等相关规章制度按照有关规定进行公平竞争审查"},{"k":"C","t":"依托全国一体化大数据中心协同创新体系布局，构建综合交通大数据中心体系"},{"k":"D","t":"防止利用数据、算法、技术等手段排除限制竞争、侵害从业人员合法权益"}],"answer":"A","multi":false,"explanation":"<p>本题考查理论与政策。<br>2024年12月12日，《中共中央办公厅 国务院办公厅关于加快建设统一开放的交通运输市场的意见》（以下简称《意见》）发布。<br>A项错误，《意见》在“二、深化交通运输重点领域改革”部分指出：“（六）推动交通运输绿色智慧转型升级······完善交通运输装备能源清洁替代政策，推动中重型卡车、船舶等运输工具应用新能源、清洁能源······”故并非“全类运输工具应用新能源、清洁能源”。<br>B项正确，《意见》在“三、完善交通运输市场制度”部分指出：“（十）完善交通领域价格机制······对交通运输领域招标投标、政府采购、经营行为规范、资质标准等相关规章制度按照有关规定进行公平竞争审查，维护公平竞争市场秩序。”<br>C项正确，《意见》在“四、优化交通运输市场要素资源配置”部分指出：“（十六）推进数据和技术赋能交通运输发展。依托全国一体化大数据中心协同创新体系布局，构建综合交通大数据中心体系······”<br>D项正确，《意见》在“五、完善交通运输市场监管机制”部分指出：“（十九）强化反垄断和反不正当竞争。加强交通运输领域市场竞争状况评估，依法查处垄断和不正当竞争行为，防止利用数据、算法、技术等手段排除限制竞争、侵害从业人员合法权益······”<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":7,"pid":"p52147c311e"},{"qid":"13504478","no":9,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记指出，如期实现建军一百年奋斗目标，加快把人民军队建成世界一流军队，是全面建设社会主义现代化国家的战略要求。关于实现建军一百年奋斗目标，下列举措恰当的是：<br>①加强军史学习教育，繁荣发展强军文化，强化战斗精神培育<br>②加强军人军属荣誉激励和权益保障，做好退役军人服务保障工作<br>③积极开展军事斗争，塑造安全态势，遏控危机冲突，阻止局部战争<br>④研究掌握信息化智能化战争特点规律，创新军事战略指导，发展人民战争战略战术</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，党的二十大报告在“十二、实现建军一百年奋斗目标，开创国防和军队现代化新局面”部分指出：“全面加强人民军队党的建设，确保枪杆子永远听党指挥······加强军史学习教育，繁荣发展强军文化，强化战斗精神培育。”<br>②正确，党的二十大报告在“十二、实现建军一百年奋斗目标，开创国防和军队现代化新局面”部分指出：“加强军人军属荣誉激励和权益保障，做好退役军人服务保障工作。”<br>③错误，党的二十大报告在“十二、实现建军一百年奋斗目标，开创国防和军队现代化新局面”部分指出：“加强军事力量常态化多样化运用，坚定灵活开展军事斗争，塑造安全态势，遏控危机冲突，打赢局部战争。”故\"积极开展军事斗争\"“阻止局部战争”表述错误，应为“灵活开展军事斗争”“打赢局部战争”。<br>④正确，党的二十大报告在“十二、实现建军一百年奋斗目标，开创国防和军队现代化新局面”部分指出：“研究掌握信息化智能化战争特点规律，创新军事战略指导，发展人民战争战略战术。”<br>故①②④表述正确。<br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":8,"pid":"p52147c311e"},{"qid":"13504370","no":10,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，现代化产业体系是现代化国家的物质技术基础，必须把发展经济的着力点放在实体经济上，为实现第二个百年奋斗目标提供坚强物质支撑。下列与之相关说法正确的有几项？<br>①推进实施绿色发展战略，充分发挥绿色化赋能实体经济发展效应<br>②促进数字技术和实体经济深度融合，催生新产业新业态新模式替代传统产业<br>③重视现代服务业的发展，推动现代服务业与先进制造业、现代农业深度融合<br>④推动重点产业在国内外有序转移、促进国内外产业深度融合与实体经济发展相结合</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，《新型工业化是发展新质生产力的主阵地》中指出，习近平总书记强调：“要充分认识形成绿色发展方式和生活方式的重要性、紧迫性、艰巨性。”······因此，要推动绿色发展与实体经济发展相融合，充分发挥绿色化赋能实体经济发展效应。<br>②错误，《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》中指出，促进数字技术与实体经济深度融合，赋能传统产业转型升级，催生新产业新业态新模式，壮大经济发展新引擎。<br>③正确，《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》中指出，重视现代服务业的发展，推动现代服务业与先进制造业、现代农业深度融合，深化业务关联、链条延伸、技术渗透，支持智能制造系统解决方案、流程再造等新型专业化服务机构发展。培育具有国际竞争力的服务企业。<br>④正确，习近平总书记在二十届中央政治局第二次集体学习时强调，优化生产力布局，推动重点产业在国内外有序转移，支持企业深度参与全球产业分工和合作，促进内外产业深度融合，打造自主可控、安全可靠、竞争力强的现代化产业体系。这要求我们发挥好超大规模市场优势和超大纵深空间优势，加快建设以实体经济为支撑的现代化产业体系，引导产业合理有序梯度转移。<br>故①③④表述正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":9,"pid":"p52147c311e"},{"qid":"13504663","no":11,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，要加强新时代廉洁文化建设，教育引导广大党员、干部增强不想腐的自觉，清清白白做人、干干净净做事。下列属于加强新时代廉洁文化建设的举措有几项？<br>①开办红色廉洁文化专题展览，在红色教育中传承党的廉洁基因<br>②对新入职党员、干部及时开展廉洁教育，扣好年轻干部廉洁从政第一粒扣子<br>③注重从优秀传统家训家规中汲取营养，开展红色家风传承活动<br>④挖掘历史文献、文化经典、文物古迹中的廉洁思想，整理古圣先贤、清官廉吏的嘉言懿行</p>","options":[{"k":"A","t":"1项"},{"k":"B","t":"2项"},{"k":"C","t":"3项"},{"k":"D","t":"4项"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，《关于加强新时代廉洁文化建设的意见》指出：“注重发掘总结党反对腐败、建设廉洁政治的历史和经验，提炼革命文化蕴含的廉洁理念，运用好革命博物馆、纪念馆、党史馆等红色资源，开办红色廉洁文化专题展览，在红色教育中传承党的廉洁基因。”<br>②正确，《关于加强新时代廉洁文化建设的意见》指出：“对新入职党员、干部及时开展廉洁教育，扣好年轻干部廉洁从政第一粒扣子。”<br>③正确，《关于加强新时代廉洁文化建设的意见》指出：“注重从优秀传统家训家规中汲取营养，开展红色家风传承活动，把对党忠诚纳入家庭家教家风建设。”<br>④正确，《关于加强新时代廉洁文化建设的意见》指出：“挖掘历史文献、文化经典、文物古迹中的廉洁思想，整理古圣先贤、清官廉吏的嘉言懿行，推动中华优秀传统文化创造性转化、创新性发展。”<br>故①②③④表述正确，有4项。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":10,"pid":"p52147c311e"},{"qid":"13504480","no":12,"type":"新思想","module":"政治理论","stem":"<p>党的二十大强调，国家安全是民族复兴的根基，社会稳定是国家强盛的前提，必须坚定不移贯彻总体国家安全观，把维护国家安全贯穿党和国家工作各方面全过程，确保国家安全和社会稳定。下列表述不正确的是：</p>","options":[{"k":"A","t":"坚持党中央对国家安全工作的集中统一领导，完善高效权威的国家安全领导体制"},{"k":"B","t":"坚持安全第一、应急为主，建立大安全大应急框架，完善公共安全体系"},{"k":"C","t":"加强海外安全保障能力建设，维护我国公民、法人在海外合法权益"},{"k":"D","t":"强化食品药品安全监管，健全生物安全监管预警防控体系"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>A项正确，党的二十大报告中“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（一）健全国家安全体系。坚持党中央对国家安全工作的集中统一领导，完善高效权威的国家安全领导体制。”<br>B项错误，党的二十大报告中“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（三）提高公共安全治理水平。坚持安全第一、预防为主，建立大安全大应急框架，完善公共安全体系，推动公共安全治理模式向事前预防转型。”因此“应急为主”表述错误。<br>C项正确，党的二十大报告“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（二）增强维护国家安全能力。坚定维护国家政权安全、制度安全、意识形态安全，加强重点领域安全能力建设，确保粮食、能源资源、重要产业链供应链安全，加强海外安全保障能力建设，维护我国公民、法人在海外合法权益，维护海洋权益，坚定捍卫国家主权、安全、发展利益。”<br>D项正确，党的二十大报告“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分指出：“（三）提高公共安全治理水平······提高防灾减灾救灾和重大突发公共事件处置保障能力，加强国家区域应急力量建设。强化食品药品安全监管，健全生物安全监管预警防控体系。加强个人信息保护。”<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":11,"pid":"p52147c311e"},{"qid":"12881996","no":13,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届三中全会提出，要健全社会治理体系。关于健全社会治理体系，下列表述不准确的是：</p>","options":[{"k":"A","t":"健全城乡社区治理体系，及时把矛盾纠纷化解在基层、化解在萌芽状态"},{"k":"B","t":"提高市域社会治理能力，强化市民热线等公共服务平台功能"},{"k":"C","t":"坚持和发展“枫桥经验”是健全社会治理体系的基础和前提"},{"k":"D","t":"健全发挥家庭家教家风建设在基层治理中作用的机制"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>A项正确，党的二十大报告中“十一、推进国家安全体系和能力现代化，坚决维护国家安全和社会稳定”部分的“（四）完善社会治理体系”指出：“······在社会基层坚持和发展新时代‘枫桥经验’，完善正确处理新形势下人民内部矛盾机制，加强和改进人民信访工作，畅通和规范群众诉求表达、利益协调、权益保障通道，完善网格化管理、精细化服务、信息化支撑的基层治理平台，健全城乡社区治理体系，及时把矛盾纠纷化解在基层、化解在萌芽状态。”<br>B、D两项正确，《中共中央关于进一步全面深化改革、推进中国式现代化的决定》（以下简称《决定》）中“十三、推进国家安全体系和能力现代化”部分的“（52）健全社会治理体系”指出：“提高市域社会治理能力，强化市民热线等公共服务平台功能，健全‘高效办成一件事’重点事项清单管理机制和常态化推进机制。健全社会心理服务体系和危机干预机制。健全发挥家庭家教家风建设在基层治理中作用的机制。深化行业协会商会改革。健全社会组织管理制度。”<br>C项错误，《决定》中“十三、推进国家安全体系和能力现代化”部分的“（52）健全社会治理体系”指出：“坚持和发展新时代‘枫桥经验’，健全党组织领导的自治、法治、德治相结合的城乡基层治理体系，完善共建共治共享的社会治理制度。”健全社会治理体系是一个复杂的系统工程，涉及到诸多方面的基础和前提条件。坚持和发展“枫桥经验”是健全社会治理体系的重要内容和有效途径，具有极其重要的作用。故“基础和前提”这种表述不准确。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":12,"pid":"p52147c311e"},{"qid":"13504421","no":1,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>司马迁说：“余读孔氏书，想见其为人。适鲁，观仲尼庙堂······祗回留之，不能去。”“余读《离骚》······悲其志。适长沙，观屈原所自沉渊······想见其为人。”《史记》的“太史公曰”据信有120余篇，大多<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，彰显客观公正的史学观。唯有对孔子和屈原则是带着浓烈的个人情感，以基本相同的笔调，发出了触动人们心灵的赞叹。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"隐晦曲折"},{"k":"B","t":"直言不讳"},{"k":"C","t":"秉笔直评"},{"k":"D","t":"光明正大"}],"answer":"C","multi":false,"explanation":"<p>横线后“彰显客观公正的史学观”对横线处进行解释说明，且需要与后文“唯有对孔子和屈原则是带着浓烈的个人情感”形成语义相反，因此横线处应体现《史记》的“太史公曰”是秉持客观公正的态度、不带有过多个人情感来进行书写。C项“秉笔直评”指拿起笔不加隐讳地径直写出，置于文段可体现出《史记》的“太史公曰”不隐瞒、不夸大、真实地反映情况之意，符合文意，当选。A项“隐晦曲折”指写文章或说话时用隐隐约约、转弯抹角的方式来表达某种思想，无法体现出客观公正之意，与文意不符，排除；B项“直言不讳”指说话坦率，毫无顾忌，侧重表达方式的直白坦率，与文段强调《史记》“太史公曰”的内容客观公正无关，与文意不符，排除；D项“光明正大”形容襟怀坦白，行为正派，而横线处修饰《史记》“太史公曰”的写作内容，并非行为，搭配不当，排除。<br>故正确答案为C。<br>【文段出处】《屈原的文化高度：与日月同辉》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":13,"pid":"p52147c311e"},{"qid":"13504674","no":2,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>全球粒子物理研究主要强国纷纷提出了各自未来的“希格斯工厂”方案。最近几年，在一些国家和地区制定的粒子物理发展规划中，希格斯粒子的研究<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地均居于核心地位。中国物理学会高能物理分会的决议中，也明确写明，我国提出的环形正负电子对撞机是我国未来高能加速器物理发展的首选项目。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"一成不变"},{"k":"B","t":"千篇一律"},{"k":"C","t":"出乎意料"},{"k":"D","t":"无一例外"}],"answer":"D","multi":false,"explanation":"<p>根据横线前“主要强国纷纷提出了各自未来的‘希格斯工厂’方案”以及横线之后的“中国物理学会高能物理分会的决议中，也明确写明”可知，文段意在说明包括中国在内的多个国家和地区都把希格斯粒子的研究提到了粒子物理发展规划的核心地位，D项“无一例外”指都是这样，没有其他特殊的，符合文意，当选。<br>A项“一成不变”指一经形成，不再改变，亦泛指墨守成规，不知变通，与文意不相符，排除；<br>B项“千篇一律”指事物只有一种形式，呆板无新意，文段并非强调一些国家和地区的研究没有新意、没有变化，而是强调大家均如此，与文意不相符，排除；<br>C项“出乎意料”指事先对情况与结果的估计，超出人们的料想猜测，与文意相悖，排除。<br>故正确答案为D。<br>【文段出处】光明日报《对撞机，究竟是个什么机》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":14,"pid":"p52147c311e"},{"qid":"13504672","no":3,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>从航天任务连战连捷到重大航空工程深入推进，从空间科学探索到航天科技成果服务经济社会发展，十年来，一次次振奋人心的火箭腾飞，一项项令人惊叹的航空成就，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>出航天人接续奋斗的轨迹。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"见证"},{"k":"B","t":"描摹"},{"k":"C","t":"创造"},{"k":"D","t":"勾勒"}],"answer":"D","multi":false,"explanation":"<p>搭配“轨迹”，且根据“一次次振奋人心的火箭腾飞，一项项令人惊叹的航空成就”可知，横线处应表达展现出了航天人接续奋斗的轨迹之意，D项“勾勒”指用线条描画出轮廓，与“轨迹”搭配恰当，且符合文意，当选。A项“见证”指当场目睹可以做证，与文意不符，且与“轨迹”搭配不当，排除；B项“描摹”指照原样描写或描画，文段并未体现照原样之意，与文意不符，排除；C项“创造”指想出新方法、建立新理论、做出新的成绩或东西，与“轨迹”搭配不当，排除。<br>故正确答案为D。<br>【文段出处】人民网《10年来航天任务连战连捷 重大工程深入推进》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":15,"pid":"p52147c311e"},{"qid":"13504391","no":4,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>说起中国的民居建筑，人们想到的多是南徽北晋，其实关中的建筑风格<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，中国最早的房屋建筑便出现在关中临潼姜寨仰韶文化村落遗址。从关中各地聚集而成的关中民俗博物院，将古时关中民宅的建筑风格<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>呈现，让我们在艺术的熏陶中感受到关中建筑的伟大。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"青出于蓝 透彻"},{"k":"B","t":"后来居上 畅快"},{"k":"C","t":"技高一筹 全面"},{"k":"D","t":"更胜一筹 淋漓"}],"answer":"D","multi":false,"explanation":"<p>第一空，搭配“建筑风格”，且根据文意可知，横线处所填成语应表达关中的建筑风格更好之意。D项“更胜一筹”指技艺或技能比较起来，比别人更好一些，符合文意，保留。A项“青出于蓝”比喻学生超过老师或后人胜过前人，B项“后来居上”指后来的超过先前的，二者均侧重后者超越前者，文段并未涉及后者与前者的比较，与文意不符，排除；C项“技高一筹”指技术高人一等，与“建筑风格”搭配不当，排除。<br>第二空，代入验证。根据“让我们在艺术的熏陶中感受到关中建筑的伟大”可知，横线处应体现关中民俗博物馆将古时关中民宅的建筑风格充分呈现之意。D项“淋漓”形容文章或说话表达得非常充分、透彻；也可形容非常痛快，符合文意，当选。<br>故正确答案为D。<br>【文段出处】人民周刊《关中民居中的秦人风骨》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":16,"pid":"p52147c311e"},{"qid":"13504676","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>大数据、人工智能、虚拟现实等新兴技术不断改写信息传播<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，“融媒”“智媒”快速迭代升级。在万物皆媒、虚实同构的传播语境下，融会贯通不同传播主体、不同传播方式，实现资源跨国配置、价值跨界创造，尤其是要<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>各国青年群体的媒介使用习惯和内容选择偏好，研究他们在视听文本、审美旨趣方面的特点，才能有效地增强中华文明的国际影响力。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"模式 认清"},{"k":"B","t":"版图 熟悉"},{"k":"C","t":"格局 洞悉"},{"k":"D","t":"形式 明确"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“大数据、人工智能、虚拟现实等新兴技术不断改写信息传播”及“‘融媒’‘智媒’快速迭代升级”可知，横线处所填词语应体现新兴技术改变了信息传播的方式、状态。A项“模式”指某种事物的标准形式或使人可以照着做的标准样式，C项“格局”指结构和格式，D项“形式”指事物的形状、结构等，均符合文意，保留。B项“版图”原指户籍和地图，今借指国家的领土、疆域，与文意无关，且与“信息传播”搭配不当，排除。<br>第二空，“尤其”表递进，且根据“有效地增强中华文明的国际影响力”可知，横线处所填词语程度较重，体现出要深入了解各国青年群体的媒介使用习惯和内容选择偏好，C项“洞悉”指很清楚地知道，强调深入、透彻地了解，程度轻重与文段相符，当选。A项“认清”指认识清楚，D项“明确”指清晰明白而确定不移，与“洞悉”相比，均程度较轻，排除。<br>故正确答案为C。<br>【文段出处】人民日报《提升中华文明的传播效能（新论）》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":17,"pid":"p52147c311e"},{"qid":"13504469","no":6,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>古人说寿县“恃水以为固”，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。五代十国时期，后周大军将寿县重重包围，守将刘仁瞻誓死守城。后遇大雨，淮河淝水暴涨后周兵营水深数尺，死伤严重，不战而退。春秋战国时，寿县是可与洛阳、邯郸、临淄<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的重要都会。自晋到唐、宋，寿县也以繁华著称于世，舟楫如梭，商贾如云。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"所言不虚 比肩"},{"k":"B","t":"言之有理 媲美"},{"k":"C","t":"当之无愧 鼎峙"},{"k":"D","t":"名不虚传 扛鼎"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据后文“五代十国时期······后周兵营水深数尺，死伤严重，不战而退”可知，横线处所填成语应体现“古人说寿县‘恃水以为固’”的说法是正确的，符合客观事实的，A项“所言不虚”指所说的话真实可靠，D项“名不虚传”指流传的名声和实际相符合，均符合文意，保留。B项“言之有理”指说的话有道理，侧重强调说话有道理，文段强调古人对寿县的点评是正确的，而非有道理，排除；C项“当之无愧”指担得起某种荣誉或某个职务，无须感到惭愧，文段并未涉及荣誉或职务，排除。<br>第二空，根据“春秋战国时，寿县是······重要都会”以及“自晋到唐、宋，寿县也以繁华著称于世”可知，寿县在当时是非常重要的城市，与洛阳、邯郸、临淄的地位不相上下，A项“比肩”指并肩，也比喻地位相等，符合文意，当选。D项“扛鼎”指举鼎，常用来比喻有大才，能负重任，也比喻攘夺国家政权，其词义均与文意无关，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":18,"pid":"p52147c311e"},{"qid":"13504426","no":7,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>江南文化的价值不仅局限于文化典籍和文物古迹之中，更<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>在人们的日常生活之中。具有几千年江河湖海水韵的江南文化，以其精神文明、文化特征和风俗习惯，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>和影响着一代又一代民众创造有烟火气、有温度的诗性生活。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"包含 汇聚"},{"k":"B","t":"蕴含 融汇"},{"k":"C","t":"酝酿 叠合"},{"k":"D","t":"孕育 萦绕"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“江南文化的价值不仅局限于······中，更······”可知，横线处应表示江南文化的价值还存在于人们的日常生活中。B项“蕴含”指包含、内部含有，符合文意，保留。A项“包含”指某事物内部含有其他内容或成分，常用于描述具体事物的组成或归属，与“江南文化价值”无法搭配，排除；C项“酝酿”是造酒的发酵过程，比喻做准备工作，江南文化的价值已存在，并非事前准备，与文意不符，排除；D项“孕育”指怀胎生育，比喻既存的事物中酝酿着新事物，江南文化的价值已存在，并非新事物，与文意不符，排除。<br>第二空，代入验证，B项“融汇”指汇聚融合，置于此处既体现江南文化对多元元素的整合，又与“影响”形成逻辑并列，凸显文化对民众生活的渗透与塑造，当选。<br>故正确答案为B。<br>【文段出处】旅游时报《曹伟明：文化江南——“上善若水”的智慧特质》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":19,"pid":"p52147c311e"},{"qid":"13504684","no":8,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>历史上的一切医学手段都包含着<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的改善身体的愿望。鉴于生命科学对于人类生物学结构和功能的理解仍然非常<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，在脑科学领域尤其如此，故不能指望生物技术在短期内对人类本性做出实质性的改变，但“更好的人类”这个未来的发展趋势已经出现。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"显而易见  通俗"},{"k":"B","t":"尽善尽美  粗浅"},{"k":"C","t":"朴实无华  晦涩"},{"k":"D","t":"不言而喻  有限"}],"answer":"D","multi":false,"explanation":"<p>第一空，横线处修饰“改善身体的愿望”，医学手段必然是为了改善身体。A项“显而易见”意思是事情或道理很明显，极容易看清，D项“不言而喻”指不用说就可以明白，也形容道理很浅显，均符合文意，保留。B项“尽善尽美”指极其完善，极其美好，形容事物完美到没有一点缺点，C项“朴实无华”指质朴实在而不浮华，均与文意无关，排除。<br>第二空，搭配“理解”，且根据“故不能指望生物技术在短期内对人类本性做出实质性的改变”可知，横线处应体现“生命科学对于人类生物学结构和功能的理解”还不够。D项“有限”指有一定的限制，符合文意，当选。A项“通俗”意思是浅显易懂且适合大众的水准，通常用来形容语言表达或内容，与“理解”搭配不当，排除。<br>故正确答案为D。<br>【文段出处】《演化视野下的人类史分期问题探讨》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":20,"pid":"p52147c311e"},{"qid":"13504675","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>综合，意味着包容和吸纳。武术、杂技、魔术等表演“绝活儿”，凡是有益于戏曲创作的，皆可为戏曲所用。当下流行的“跨界融合”，无论是戏曲汲取其他当代艺术元素的创新，还是戏曲给予其他艺术样式灵感与素材，实质上都与中国戏曲综合性艺术特征相<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。综合意味着<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，而不是自设边界。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"契合 吐故纳新"},{"k":"B","t":"投合 兼收并蓄"},{"k":"C","t":"迎合 推陈出新"},{"k":"D","t":"符合 融会贯通"}],"answer":"A","multi":false,"explanation":"<p>第一空，搭配“艺术特征”，且根据前文“综合，意味着包容和吸纳”可知，文段强调“跨界融合”与中国戏曲综合性艺术特征在本质上是相同的，故横线处所填词语要体现出相同、相符之意。A项“契合”指符合，D项“符合”指相合，均符合文意，保留。B项“投合”指相合、合得来，多表述为意气投合、性情投合，与“艺术特征”搭配不当，排除；C项“迎合”指有意使自己的言行或举动适合别人心意，感情色彩偏消极，与文段感情色彩不符，排除。<br>第二空，根据“无论是戏曲汲取其他当代艺术元素的创新”以及“意味着······而不是”可知，横线处所填成语与“自设边界”语义相反，强调戏曲应当对外开放，并汲取创新元素，A项“吐故纳新”比喻扬弃旧的，吸收新的，符合文意，当选。D项“融会贯通”指各方面的知识或道理融合贯穿起来，从而得到系统透彻的理解，未提及“汲取创新元素”之意，排除。<br>故正确答案为A。<br>【文段出处】光明网《戏曲创新 从源头活水到海纳百川》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"p52147c311e"},{"qid":"12881999","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>新文化运动作为一场思想文化领域的革命，实际构建了<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>传统儒学意识形态的现代意识形态。新文化运动时期形成的社会观、伦理观、中西文化观对<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>中国现代的社会形态提供了观念性的基础。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"赓续 改进"},{"k":"B","t":"替代 形塑"},{"k":"C","t":"取用 重构"},{"k":"D","t":"转换 完善"}],"answer":"B","multi":false,"explanation":"<p>第一空，搭配“现代意识形态”，根据文意可知，横线处表达现代意识形态取代了传统儒学意识形态之意，B项“替代”指代替，符合文意，且与“现代意识形态”搭配恰当，保留。A项“赓续”指延续，C项“取用”指拿来使用，采用，均与文意不符，排除；D项“转换”指改变、改换，文段并非表达使传统儒学意识形态发生改变之意，而是强调现代意识形态取代了传统儒学意识形态，与文意不符，排除。<br>第二空，代入验证。搭配“社会形态”，B项“形塑”指形成、塑造，与“社会形态”搭配恰当，当选。<br>故正确答案为B。<br>【文段出处】《欧阳哲生：新文化运动的文献整理与历史诠释——编辑&lt;复兴文库·新文化运动&gt;卷之旨趣》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"p52147c311e"},{"qid":"12881997","no":11,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>福建屏南，群峰耸峙、雨量<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，孕育了茂密的竹海，也造就了屏南传统竹木弓箭制作技艺。一代代弓箭工匠，致力于<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>竹木弓箭制作工艺、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>传统竹木射箭运动，让传统体育运动重新焕发光彩。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"充足 再现 恢复"},{"k":"B","t":"充沛 复原 复兴"},{"k":"C","t":"丰沛 修复 弘扬"},{"k":"D","t":"充实 还原 振兴"}],"answer":"B","multi":false,"explanation":"<p>第一空，横线处所填词语搭配“雨量”，且根据“孕育了茂密的竹海”可知，横线处所填词语需体现出雨量丰富，为屏南的自然环境提供了充足的水分，A项“充足”指足够、充分，B项“充沛”指充足、旺盛，常用于形容精力、感情或雨量，C项“丰沛”指丰富、充足，多用于形容雨水、物产，均符合文意，保留；D项“充实”指丰富、充足（多指内容或人员物力的配备），与“雨量”搭配不当，排除。<br>第二空，搭配“制作工艺”，且根据“让传统体育运动重新焕发光彩”可知，横线处所填词语需体现出工匠们努力恢复或重现传统工艺之意，A项“再现”指再次出现，重现，B项“复原”指恢复原状，均符合文意，保留；C项“修复”指修理使恢复完整，多用于破损物品的修复，与“制作工艺”搭配不当，排除。<br>第三空，根据“让传统体育运动重新焕发光彩”可知，横线处所填词语需体现出使传统竹木射箭运动重新兴盛之意，B项“复兴”指再次兴盛，符合文意，当选；A项“恢复”仅指回到原有状态，无法体现出“重新兴盛”之意，排除。<br>故正确答案为B。<br>【文段出处】人民日报《复原制作技艺，复兴传统射箭运动，福建屏南——一张竹木弓的铿锵回响（关注体育产业·工匠精神）》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"p52147c311e"},{"qid":"13504428","no":12,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>网络直播本质而言是一种“眼球经济”，极具效仿意味和引导效应。如果本该弘扬正能量、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>真善美的镜头，却频频出现打擦边球、违背社会公序良俗的行为，那么长此以往不仅会<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>直播行业的健康发展，也会<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>风清气正的环境。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"散布 妨碍 损害"},{"k":"B","t":"撒播 阻挠 腐化"},{"k":"C","t":"传递 干扰 摧毁"},{"k":"D","t":"传播 阻碍 侵蚀"}],"answer":"D","multi":false,"explanation":"<p>第一空，搭配“真善美”，C项“传递”指由一方交给另一方，D项“传播”指广泛散布、传递，均与“真善美”搭配恰当，保留。A项“散布”指分散到各处或广泛传播，多用于消极语境，如“散布谣言”等，与横线处的感情色彩不符，排除；B项“撒播”一般指把种子均匀地撒在田地里，常搭配具体对象，与“真善美”这一抽象概念搭配不当，排除。<br>第二空，根据“却频频出现打擦边球、违背社会公序良俗的行为”可知，横线处应体现不良的网络直播行为对直播行业健康发展产生消极影响之意。C项“干扰”意思是打扰、妨碍，D项“阻碍”指使不能顺利通过或发展，均符合文意，保留。<br>第三空，搭配“环境”，且根据前文可知，横线处应体现不良的网络直播行为对风清气正的环境产生不利影响之意。D项“侵蚀”指逐渐侵害使变坏，与“环境”搭配恰当，且符合文意，当选。C项“摧毁”指用强大的力量破坏，“摧毁风清气正的环境”程度过重，排除。<br>故正确答案为D。<br>【文段出处】人民网《人民艺起评：莫让低俗成为网络直播的标签》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"p52147c311e"},{"qid":"13504467","no":13,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>在实现第二个百年奋斗目标的新征程上，我们既拥有了强大的思想伟力、显著的制度优势，积累了<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的物质基础、建立了<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的产业体系和超大规模的国内市场，又面临着诸多风险挑战，甚至可能遇到难以想象的惊涛骇浪般的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>考验。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"雄厚 完备 严峻"},{"k":"B","t":"丰厚 完善 巨大"},{"k":"C","t":"厚实 完美 严酷"},{"k":"D","t":"浑厚 完整 重大"}],"answer":"A","multi":false,"explanation":"<p>第一空，搭配“物质基础”，且由后文的“超大规模的国内市场”，可知所填词语需体现物质基础很充足的意思，A项“雄厚”指（人力、物力等）充足，B项“丰厚”指丰富、多，C项“厚实”指深厚扎实，均符合文意，保留。D项“浑厚”指朴实厚重，也形容说话、唱歌、朗诵等声音低沉有力，常与“声音、气势、力量”等搭配，与“物质基础”搭配不当，排除。<br>第二空，搭配“产业体系”，A项“完备”指应该具备的全部具备，B项“完善”指完备良好，均与“产业体系”搭配恰当，保留。C项“完美”指完备美好，没有缺陷，强调事物没有任何缺点，由后文“面临着诸多风险挑战，甚至可能遇到难以想象的惊涛骇浪般的······考验”可知，当前的产业体系并非完美无瑕，排除。<br>第三空，搭配“考验”，且由前文提到\"面临着诸多风险挑战，甚至可能遇到难以想象的惊涛骇浪般的······考验\"可知，这些考验具有极高的难度和挑战性。A项“严峻” 意为严厉、严肃、严重，常与 “考验、挑战、形势” 等搭配，能够突出这些考验的艰难程度高、具有较强的紧迫性，与前文 “诸多风险挑战”“难以想象的惊涛骇浪般” 所营造的紧张、艰难的语境相契合，符合文意，当选。B项 “巨大” 主要侧重于形容规模、数量、程度等方面非常大，比如 “巨大的工程”“巨大的力量” 等，“巨大的考验” 更多强调的是考验在规模或程度上的庞大，无法准确体现出此处所面临考验的艰巨性，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】《理解伟大建党精神的三个重要维度》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"p52147c311e"},{"qid":"13504436","no":14,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>青春的样子，本就是有理想、敢担当、能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、肯奋斗的样子。树立积极的就业观念，到祖国和人民最需要的地方发挥光和热，在乡村振兴、卫国戍边等各领域各方面工作中争当排头兵和生力军，不仅能够留下无悔的青春记忆，而且将在基层<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>中获得受用终身的精神财富，为走好职业生涯提供<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的滋养。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"作为 磨难 日久弥新"},{"k":"B","t":"刻苦 磨练 经久不衰"},{"k":"C","t":"吃苦 磨砺 源源不断"},{"k":"D","t":"奉献 磨炼 滔滔不竭"}],"answer":"C","multi":false,"explanation":"<p>第一空，搭配“能”，且体现青春的样子。C项“吃苦”指经受艰苦，D项“奉献”指付出，不求回报，均与“能”搭配恰当且符合文意，保留。A项“作为”指建树，成就，通常表述为“有作为”而非“能作为”，排除；B项“刻苦”指肯下苦功夫、能吃苦，为形容词，置于文段用法错误，排除。<br>第二空，横线处所填词语体现在基层历练中获得精神财富。C项“磨砺”和D项“磨炼”均指在艰难困苦的环境中锻炼，符合文意，保留。<br>第三空，搭配“滋养”，且根据“获得受用终身的精神财富”可知，精神财富可以滋养终身。C项“源源不断”形容接连不断，符合文意，当选。D项“滔滔不竭”意思是像流水一样连续不断，形容话多，与“滋养”搭配不当，排除。<br>故正确答案为C。<br>【文段出处】人民日报《人民时评：树立正确的就业观》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"p52147c311e"},{"qid":"12882002","no":15,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>冠心病、心肌梗塞、脑梗塞、下肢坏死······糖尿病带来的并发症令人痛苦不堪，更麻烦的是，它还会<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>认知障碍，例如轻度认知损伤和阿尔茨海默病。有研究显示，近十几年来，在死亡的糖尿病患者中，患有认知障碍的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>越来越大。因此，亟须找到引发糖尿病患者认知障碍的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"激发 比值 元凶巨恶"},{"k":"B","t":"导致 比例 幕后黑手"},{"k":"C","t":"诱发 比重 罪魁祸首"},{"k":"D","t":"招致 比率 始作俑者"}],"answer":"C","multi":false,"explanation":"<p>第一空，搭配“认知障碍”，根据“糖尿病带来的并发症令人痛苦不堪，更麻烦的是”可知，横线处应体现糖尿病会引发认知障碍这类不好的结果之意，B项“导致”指造成，常用于不好的结果，C项“诱发”指导致发生（多指疾病），D项“招致”指引起（后果），三者均符合文意，保留。A项“激发”指刺激使奋发，常搭配“动能”“活力”等，与“认知障碍”搭配不当，排除。<br>第二空，根据“在死亡的糖尿病患者中”可知，横线处应表示在这一范围内患有认知障碍的占比情况，B项“比例”指比重，C项“比重”指一种事物在整体中所占的分量，D项“比率”指比值，均能体现这种占比关系，保留。<br>第三空，“因此”引导因果关系，根据“在死亡的糖尿病患者中，患有认知障碍的        越来越大”可知，横线处应体现亟须找到引发糖尿病患者认知障碍的原因，为其预防或治疗提供依据，C项“罪魁祸首”指作恶犯罪的头目，也指灾祸的主要原因，置于此处可以形象地表达出要找到导致认知障碍的主要原因，符合文意，当选。B项“幕后黑手”指在背后起到推动作用的人或力量，常带有较强人为故意、阴谋诡计的意味，D项“始作俑者”比喻第一个做某项坏事的人或恶劣风气的创始人，文段仅强调要找到糖尿病引发认知障碍的原因，而非查找暗中操作的人或者创始人是谁，均与文意不符，排除。<br>故正确答案为C。<br>【文段出处】科技日报《脂肪中小分子“作恶”，影响糖尿病患者认知》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"p52147c311e"},{"qid":"13504468","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>起伏越多越大的地形，越不利于上方气流的稳定，因此，在山地丘陵和城镇的上空，哪怕雷暴云产生了滚轴云，也很容易因地形的扰乱而被迅速破坏。而在广袤、平坦的海洋上空，滚轴云却可以经久不散。同样广袤的内蒙古大草原，看起来也理应利于滚轴云的频繁生成。但是，与大海低空湿润的空气相比，草原低空的空气未必湿润，而暖湿气流是雷暴云生长的基础。如果低空湿度不够，雷暴云即使形成，也难以在低空中形成大量的云体。<br>这段文字主要介绍了：</p>","options":[{"k":"A","t":"滚轴云是雷暴云生长的前提"},{"k":"B","t":"暖湿气流是滚轴云形成的基础"},{"k":"C","t":"地形和湿度是雷暴云形成的关键"},{"k":"D","t":"内陆中滚轴云比海洋更少的原因"}],"answer":"D","multi":false,"explanation":"<p>文段开篇指出起伏大的地形不利于滚轴云稳定，山地丘陵和城镇上空的滚轴云易被破坏，接着指出海洋上空地形平坦，滚轴云可经久不散。紧接着引出内蒙古大草原，指出草原理应利于滚轴云的频繁生成，随后通过“但是”反驳前文观点，指出草原低空空气湿度不够，难以在低空中形成大量的云体。故文段并列从山地丘陵和城镇地形角度和草原低空的空气湿度两个方面说明内陆比海洋滚轴云少的原因，对应D项。<br>A项，文段强调雷暴云对滚轴云形成有影响，“滚轴云是雷暴云生长的前提”因果倒置，排除；<br>B项，“暖湿气流”仅对应湿度一个方面，表述片面，排除；<br>C项，文段中强调的是内陆与海洋滚轴云形成情况的对比，偏离重点，且文段重点强调“滚轴云”，“雷暴云”偷换概念，排除。<br>故正确答案为D。<br>【文段出处】中国国家地理《海岛 海上天象奇观的最佳观景台》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"p52147c311e"},{"qid":"13504392","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>与工业经济、数字经济相比，生物经济最大的特点是打破了数字经济“赢者通吃”的商业模式，具有资源依赖性强、技术多样性高、市场垄断程度低等特点，为生物资源丰富、生物技术相对落后的国家提供了一次难得的、可能实现跨越式发展的机遇。我国生物资源丰富、市场潜力大，生物技术已有良好基础，做强做大生物经济，不仅能有效缓解甚至最终解决粮食安全、能源安全、环境安全、生物安全等问题，而且能够大幅度提高人民健康水平，推进新一轮经济增长。<br>这段文字旨在说明：</p>","options":[{"k":"A","t":"我国生物经济的发展现状与前景研判"},{"k":"B","t":"全球生物经济演进的规律和发展布局"},{"k":"C","t":"中国面临生物经济的巨大机遇和挑战"},{"k":"D","t":"生物经济对构建新发展格局意义重大"}],"answer":"A","multi":false,"explanation":"<p>文段开篇引出“生物经济”的话题，详细介绍了生物经济的特点，并指出生物经济“为生物资源丰富、生物技术相对落后的国家提供了一次难得的、可能实现跨越式发展的机遇”。接着指出我国有良好的生物基础，并点明做大做强生物经济，不仅能有效缓解甚至最终解决粮食安全、能源安全、环境安全、生物安全等问题，而且能够大幅度提高人民健康水平，推进新一轮经济增长。故文段重在围绕“生物经济”及“我国”展开论述，强调我国发展生物经济有良好的基础，及做大做强生物经济的好处，对应A项。<br>B项，缺少文段核心话题“我国”，且“全球生物经济演进的规律和发展布局”无中生有，排除；<br>C项，“中国面临生物经济的挑战”无中生有，排除；<br>D项，缺少文段核心话题“我国”，且“新发展格局”无中生有，排除。<br>故正确答案为A。<br>【文段出处】光明网《我国生物经济发展现状与前景研判》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"p52147c311e"},{"qid":"13504490","no":18,"type":"片段阅读","module":"言语理解与表达","stem":"<p>人工智能所带来的智能化和自动化社会发展趋势提升了社会生产效率，并对传统公共管理者的决策和服务角色带来挑战。人工智能作为新型的权利所有者逐渐代替传统公共管理者，作为基于计算逻辑、算法规则和数据的公共管理者参与到社会治理过程之中，从而使未来人工智能场景下的公共管理者角色由“事务性供给”转向“公共性维护”，这一趋势在将传统的公共管理者从社会事务管理中解放出来的同时，也淡化了传统公共管理者在社会中的管理者角色，使社会治理逐渐呈现由自由平等的生产者联合治理的特点。<br>这段话所要表达的中心思想是：</p>","options":[{"k":"A","t":"人工智能消除公共权利"},{"k":"B","t":"人工智能加速生产者联合"},{"k":"C","t":"人工智能提高技术治理能力"},{"k":"D","t":"人工智能推动社会自主管理的实现"}],"answer":"D","multi":false,"explanation":"<p>文段开篇指出人工智能提升了社会生产效率，同时也为传统公共管理带来了挑战，接着指出人工智能参与到社会治理过程之中，使传统公共管理者角色由“事务性供给”转向“公共性维护”，之后通过“这一趋势”总结前文，指出人工智能对传统公共管理者带来的影响，最后通过因果标志词“使”得出结论，强调人工智能使得社会治理呈现出新特点，即社会治理由自由生产者联合治理，对应D项。<br>A项，“消除公共权利”文段并未提及，无中生有，且“消除”程度过重，文段仅为“淡化了传统公共管理者在社会中的管理者角色”，排除；<br>B项，文段强调“社会治理”模式的转变，而不是单纯强调生产者联合这一现象本身，偏离文段核心话题，排除；<br>C项，“技术治理能力”文段并未提及，无中生有，且文段核心话题为“社会治理”，“技术治理”概念偷换，排除。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":30,"pid":"p52147c311e"},{"qid":"13504411","no":19,"type":"片段阅读","module":"言语理解与表达","stem":"<p>历史早期季节体系的发展演变与农事周期之间具有紧密联系。殷商及其以前的“二时”观念是围绕种植粟、黍等农作物的农事活动而产生的一种社会时间，殷商以来对冬小麦的推广种植并使其嵌入到固有的农业结构中，推动了先秦时期人们“四时”观念的萌生与演进。所以，“四时”观念的产生，是在对既有的“二时”观念进一步细化的基础上得以实现的，而冬小麦的推广种植及其在农业生产中重要地位的逐渐凸显，成为人们细化“二时”观念为“四时”观念的契机。<br>这段文字主要讲述的是：</p>","options":[{"k":"A","t":"社会时间超过自然时间之外而独立存在"},{"k":"B","t":"先秦“四时”观念与“二时”观念的联系"},{"k":"C","t":"冬小麦的推广种植在农业生产中的重要地位"},{"k":"D","t":"冬小麦的推广种植与先秦“四时”观念的产生"}],"answer":"D","multi":false,"explanation":"<p>文段开篇指出历史早期季节体系与农事周期联系紧密，接着说明殷商及其以前的“二时”观念与农事活动相关，随后指出殷商以来冬小麦的推广种植推动了先秦时期“四时”观念的萌生与演进，最后通过结论词“所以”强调冬小麦的推广种植是人们将“二时”观念细化为“四时”观念的契机。故文段主要论述冬小麦的推广种植促进先秦“四时”观念的产生，对应D项。<br>A项，“社会时间”对应结论词前的内容“殷商······一种社会时间”，非重点，且“超过自然时间之外而独立存在”文段未提及，无中生有，排除；<br>B项未提及文段主题词“冬小麦”，C项未提及文段主题词“四时”，均排除。<br>故正确答案为D。<br>【文段出处】《小麦的推广种植与先秦时期“四时”观念的强化》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":31,"pid":"p52147c311e"},{"qid":"13504427","no":20,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在中老年患者中，动脉硬化是个常见病。当血管出现硬化病变后，很多人认为只要将硬化的血管变“软”就可以改善病情。事实上，动脉硬化是以脂质代谢障碍为基础的一类病变，以胆固醇及低密度脂蛋白为主的脂质首先在血管内膜下沉积，然后逐渐在局部形成血栓，进一步通过纤维化及钙化形成动脉硬化斑块，最终导致动脉壁增厚变硬、血管腔狭窄。动脉硬化是一个不可逆的过程，出现硬化后的血管是无法恢复到正常状态的，因此动脉硬化的进程只能延缓，不能逆转。<br>这段文字旨在说明：</p>","options":[{"k":"A","t":"硬化的血管难再“软”"},{"k":"B","t":"老年人难逃动脉硬化"},{"k":"C","t":"动脉硬化是个常见病"},{"k":"D","t":"动脉硬化是基础病变"}],"answer":"A","multi":false,"explanation":"<p>文段开篇介绍动脉硬化在中老年患者这一群体中是常见病，引出动脉硬化这一话题，接着指出很多人认为将硬化的血管变“软”可以改善病情，随后通过转折词“事实上”介绍动脉硬化的具体形成过程，尾句强调硬化后的血管是无法恢复到正常状态的，最后通过“因此”对前文进行总结，表明动脉硬化的进程只能延缓，不能逆转，即动脉硬化后的血管是无法恢复到“软”状态的，故文段为分总结构，强调硬化后的血管是无法再变“软”的，对应A项。<br>B项，“难逃动脉硬化”表述过于绝对，排除；<br>C项、D项，分别对应前文“动脉硬化是个常见病”、“动脉硬化是以脂质代谢障碍为基础的一类病变”，为结论前的内容，非重点，均排除。<br>故正确答案为A。<br>【文段出处】北京青年报《洋葱沙拉、凉拌木耳、保健醋、深海鱼油······竟都是吃了个“寂寞”——原来血管是没办法被软化的》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":32,"pid":"p52147c311e"},{"qid":"13504494","no":21,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在距今约1.26亿年至7200万年之间，树脂产量和沉积量特别大，地层里的琥珀十分丰富，该时段称为白垩纪树脂时期，比白垩纪树脂时期更早期的琥珀非常稀少，且很少包含生物；白垩纪结束后琥珀数量明显下降，近乎消失，直到6100万年前新生代地层中才开始出现新的琥珀。白垩纪树脂时期全球气候温暖湿润，大气中二氧化碳和甲烷等温室气体含量较高，频繁的火山活动促进气候变暖、改变大气成分，有利于松柏类植物生长，生物活跃、病虫害增加使树木分泌更多树脂，野火频发，促进树脂产生与埋藏，海平面上升使许多内陆低地被淹没，土层中石化树脂被冲刷、搬运、沉积形成琥珀矿藏。<br>这段文字主要介绍了白垩纪树脂时期琥珀化石的：</p>","options":[{"k":"A","t":"形态特征"},{"k":"B","t":"科学价值"},{"k":"C","t":"形成原因"},{"k":"D","t":"类别划分"}],"answer":"C","multi":false,"explanation":"<p>文段开篇指出白垩纪树脂时期琥珀非常丰富，接着论述这一时期气候温暖湿润、温室气体含量较高，以及频繁的火山活动有利于植物生长，生物活跃、病虫害增加使得树木分泌更多树脂，接着进一步指出，野火频发促进了树脂的产生与埋藏，之后论述海平面的上升使得石化树脂沉积，从而最终形成了琥珀矿藏，故整个文段重点围绕白垩纪树脂时期琥珀化石形成的全过程，介绍了其具体原因，对应C项。<br>A项“形态特征”、B项“科学价值”、D项“类别划分”文段均未提及，无中生有，排除。<br>故正确答案为C。<br>【文段出处】新华网《新研究解析白垩纪琥珀化石丰富的原因》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":33,"pid":"p52147c311e"},{"qid":"13504413","no":22,"type":"片段阅读","module":"言语理解与表达","stem":"<p>我们都知道很多植物的种子是靠动物来传播的，很多木本植物，喜欢利用鸟类来帮助它们传播种子。但对草本植物来说，有更适合它们的“工具人”——蚂蚁，而这些利用蚂蚁传播种子的植物有一个专有名词——蚁播植物。蚂蚁小，蚁播植物的种子也非常不起眼。原来，草本植物在种子上带了块营养丰富的“肉”，这个“肉”富含蚂蚁所需的油脂或者其他营养成分，而被叫做“油质体”。不管油质体种类是有多么丰富多彩，外形是有多么天差地别，但都逃不了两项原则：既要充当着诱惑蚂蚁的食物，还要作为蚂蚁叼着这些种子的抓手。<br>接下来最有可能讲的是：</p>","options":[{"k":"A","t":"蚂蚁如何处理蚁播植物"},{"k":"B","t":"“油质体”如何充当着诱惑蚂蚁的食物"},{"k":"C","t":"鸟类如何帮助木本植物传播它们的种子"},{"k":"D","t":"草本植物的“油质体”被其他植物“偷食”"}],"answer":"B","multi":false,"explanation":"<p>本题为接语选择题，应在通读全文的基础上，重点关注文段最后论述的核心话题。文段开篇指出很多植物的种子靠动物来传播，接着通过转折关联词“但”指出草本植物更适合靠蚂蚁传播种子，接着介绍草本植物种子上存在“油质体”，既要充当诱惑蚂蚁的食物，又要作为蚂蚁叼种子的抓手。故文段最后论述的核心话题为“油质体”和“蚂蚁”，且根据逻辑应先论述“油质体”如何作为食物诱惑蚂蚁，对应B项。<br>A项“蚂蚁如何处理蚁播植物”、C项“鸟类如何帮助木本植物传播种子”均偏离文段最后论述的核心话题“油质体”，排除；<br>D项“其他植物”偏离文段最后论述的核心话题“蚂蚁”，无法和尾句衔接，排除。<br>故正确答案为B。<br>【文段出处】《什么，蚂蚁竟然也能“种地”？！》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":34,"pid":"p52147c311e"},{"qid":"13504396","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>从交通出行到餐饮消费，从垃圾分类到噪声治理，群众的日常生活与城市治理息息相关。提升城市治理精细化水平，也是适应城市发展新阶段、新要求，打造宜居、韧性、智慧城市的必然要求。过去5年，我国常住人口城镇化率稳步提升，由大规模增量建设转为存量提质改造和增量结构调整并重。在这样的大背景下，燃气管网、桥梁等如何实现实时监测，红绿灯如何配时，公园绿地如何布局等，都考验着城市治理精细化水平。<br>这段文字接下来最可能介绍的是：</p>","options":[{"k":"A","t":"城市治理智能化带来的新问题"},{"k":"B","t":"如何进行城市软硬件增量建设"},{"k":"C","t":"城市精细化治理与百姓的关联性"},{"k":"D","t":"如何提升城市治理的精细化水平"}],"answer":"D","multi":false,"explanation":"<p>本题为接语选择题，需通读全文，重点关注文段最后谈论的核心话题。文段开篇引出“城市治理”这一话题，指出群众的日常生活与城市治理息息相关，随后通过“必然要求”强调提升城市治理精细化水平的重要性，并简单介绍过去5年我国城镇化发展情况，尾句通过“在这样的大背景下”对前文总结，强调诸多民生事宜都考验着城市治理精细化水平。故文段最后讨论的核心话题为“城市治理精细化水平”，根据话题一致原则，后文应继续围绕这一话题展开，对应D项。<br>A项“城市治理智能化”、B项“城市软硬件增量建设”文段均未提及，无中生有，且均未提及文段最后讨论的核心话题“城市治理精细化水平”，排除；<br>C项，文段开头以及尾句已经论述过群众的日常生活与城市精细化治理息息相关，后文不会再继续论述，且未提及文段最后讨论的核心话题“城市治理精细化水平”，排除。<br>故正确答案为D。<br>【文段出处】人民日报《城市治理要下足绣花功夫（人民时评）》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":35,"pid":"p52147c311e"},{"qid":"13504682","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>上门代厨、上门收纳整理、上门推拿、上门养老······近年来，各类上门服务新业态涌现，为市场经济输入新鲜血液。但“上门经济”并非只有红利没有烦恼。调查发现，目前“上门经济”面临监管存在盲区、消费者维权难、取证溯源难等问题，亟待加强规范引导。规范是保障行业健康有序发展、维护各方合法权益的基础。只有把规矩立起来，加强规范引导，才能促进“上门经济”良性发展。<br>最适合做这段文字标题的是：</p>","options":[{"k":"A","t":"“上门经济”规范有序方能行稳致远"},{"k":"B","t":"“上门经济”并非只有红利没有烦恼"},{"k":"C","t":"“上门经济”为市场经济输入新血液"},{"k":"D","t":"“上门经济”既要敞开门也要守好门"}],"answer":"A","multi":false,"explanation":"<p>文段开篇论述各类上门服务新业态涌现给市场经济带来活力，接着通过转折关联词“但”指出“上门经济”存在监管盲区、消费者维权难、取证溯源难等问题，并通过“亟待”提出对策，强调要对其加强规范引导，尾句通过“只有······才”再次强调，确立规矩，加强规范引导才能促进“上门经济”的良性发展。故文段为提出问题—解决问题的结构，重在提对策，强调“上门经济”的发展需加强规范引导，对应A项。<br>B项，对应文段问题表述，非重点，排除；<br>C项，对应文段开篇部分，为转折前内容，非重点，排除；<br>D项，“要敞开门也要守好门”表述不明确，未体现对策“加强规范引导”，偏离文段中心，排除。<br>故正确答案为A。<br>【文段出处】安徽日报《“上门经济”立规才能长远》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":36,"pid":"p52147c311e"},{"qid":"13504686","no":25,"type":"片段阅读","module":"言语理解与表达","stem":"<p>我国主要粮食品种供给充足，但在资源和环境双重约束下，构建多元食物供给体系还面临较大压力。现代设施农业包含设施种植、设施畜牧、设施渔业和工厂化育秧设施、粮食烘干设施、仓储冷链物流设施等公共服务设施，可以利用现代信息技术、生物技术、工程装备技术与现代经营管理方式，突破资源、环境和市场的限制，拓宽农业发展时空，缓解粮食生产面临的问题，尽可能规避市场风险。<br>与这段文字意思相符的一项是：</p>","options":[{"k":"A","t":"我国设施农业应用广泛，粮食品种供给充足"},{"k":"B","t":"现代经营管理方式构建了多元食物供给体系"},{"k":"C","t":"解决育秧难问题，须建设工厂化育秧设施"},{"k":"D","t":"现代设施农业可以突破资源、环境的制约"}],"answer":"D","multi":false,"explanation":"<p>A项，根据“我国主要粮食品种供给充足”可知，“粮食品种供给充足”范围扩大，与文意不符，排除；<br>B项，根据“构建多元食物供给体系还面临较大压力”可知，“多元食物供给体系”还没有构建完毕，与文意不符，排除；<br>C项，“育秧难问题”文段并未提及，无中生有，排除；<br>D项，根据“现代设施农业包含设施种植······突破资源、环境和市场的限制”可知，表述正确，当选。<br>故正确答案为D。<br>【文段出处】人民日报《因地制宜发展现代设施农业（纵横）》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":37,"pid":"p52147c311e"},{"qid":"13504488","no":26,"type":"语句表达","module":"言语理解与表达","stem":"<p>从事实际活动的现实的人，是马克思主义的出发点。实现人的自由全面发展是马克思主义的最高价值追求。要坚持以人民为中心，坚持人民主体地位，将人民作为改革与发展的实践主体和核心动力，将实现、维护和发展最广大人民根本利益、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、促进人的自由全面发展作为改革与发展的根本目的和最高价值，激发人民的历史主动性和创造性，促进社会公正，增进民生福祉，不断实现人民对美好生活的向往，使人民群众有更多的获得感、幸福感、安全感。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"大力发展教育培训"},{"k":"B","t":"尊重人民各项权利"},{"k":"C","t":"完善各项法律法规"},{"k":"D","t":"推动人民参与治理"}],"answer":"B","multi":false,"explanation":"<p>本题为语句填空题，横线在文段中间，需联系上下文分析，且横线为所在句子的分句，重点把握句内的衔接。文段首先指出马克思主义这一话题，随后强调马克思主义的最高价值追求是人的自由全面发展，即保证人民的权益和主体性地位。横线前后通过并列形式分别强调“实现、维护和发展最广大人民根本利益”“促进人的自由全面发展”，这三者均是改革与发展的根本目的和最高价值，即“坚持以人民为中心，坚持人民主体地位”。故横线处也应体现重视“人民”的主体性地位。后文又提到“增进民生福祉，不断实现人民对美好生活的向往，使人民群众有更多的获得感、幸福感、安全感”，即要实现人的利益与权益，对应B项。<br>A项“大力发展教育培训”，C项“完善各项法律法规”，均没有提及与人民相关的话题，排除；<br>D项“推动人民参与治理”这一对策文段并未提及，且横线处应体现改革与发展的目的和价值，并非改革与发展的具体做法，表述错误，排除。 <br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":38,"pid":"p52147c311e"},{"qid":"13504433","no":27,"type":"片段阅读","module":"言语理解与表达","stem":"<p>典籍版本资源有多种形式。除书籍外，印刷古籍的雕版，有文字记录的简帛、金石器物、石刻、碑刻、拓本、绘画、纸币、档案及近代以来各种类型的媒介等，均可纳入典籍版本资源的范畴。从广义上来说，凡是能够印证中华文明、以物证史、以物叙史、可以直观感受或触摸的实物，都可视为典籍版本资源。典籍版本资源是中华文明的“活化石”，是中国历史不绝如缕、一脉相承的“见证人”，也是中国文化影响世界的“实证者”。它为全面深入了解中华文明提供了一把钥匙，具有不可比拟的独特优势，在推动建设中华民族现代文明方面发挥着重要作用。<br>这段文字重在讨论典籍版本：</p>","options":[{"k":"A","t":"资源范畴与文化价值"},{"k":"B","t":"文献属性与社会作用"},{"k":"C","t":"形式类型与历史意蕴"},{"k":"D","t":"实物来源与优势地位"}],"answer":"A","multi":false,"explanation":"<p>文段开篇介绍典籍版本资源具有多种形式，包括书籍、雕版、简帛等，从广义上来说凡是能印证中华文明的实物都可视为典籍版本资源。此部分重点论述了典籍版本的资源范畴。随后介绍典籍版本资源是中华文明的“活化石”、是中国历史的“见证人”、是中国文化影响世界的“实证者”，为全面深入了解中华文明提供了钥匙，在推动建设中华民族现代文明方面发挥着重要作用。此部分重点强调典籍版本的文化价值。故文段为并列结构，分别论述了典籍版本的资源范畴及其文化价值，对应A项。<br>B项，文段并未提及典籍版本的“文献属性”，无中生有，排除；<br>C项，“历史意蕴”对应文段“是中国历史不绝如缕、一脉相承的‘见证人’”，仅为“文化价值”的一部分，表述片面，排除；<br>D项，“实物来源”文段并未提及，且“优势地位”相比于“文化价值”表述不明确，排除。<br>故正确答案为A。<br>【文段出处】社科院专刊总第674期《发挥典籍版本资源作用推动建设中华民族现代文明》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":39,"pid":"p52147c311e"},{"qid":"13504390","no":28,"type":"片段阅读","module":"言语理解与表达","stem":"<p>中国科学院大气物理研究所开发的起沙模型很好地模拟出了2001年至2017年东亚沙尘暴频次的年际变化和减弱趋势，模拟的起沙通量与观测的沙尘天数具有很好的相关关系，相关系数达0.75。从变化的原因来看，沙尘源区上地表风速减弱、植被覆盖增加、土壤变湿均起到了重要作用，贡献率分别为46%、30%、24%。可见，风速减弱起主导作用，而植被覆盖增加和土壤变湿也有关键作用。<br>由此可以推知：</p>","options":[{"k":"A","t":"沙尘暴的起因有三方面"},{"k":"B","t":"起沙模型还有提升空间"},{"k":"C","t":"风速减弱属于人为因素"},{"k":"D","t":"增加植被覆盖率能够减弱沙尘暴"}],"answer":"D","multi":false,"explanation":"<p>A项，文段并未介绍“沙尘暴的起因”，文段介绍的是2001-2017年沙尘暴频次的年际变化和减弱趋势的原因，无中生有，排除；<br>B项，文段并未提及起沙模型是否还有提升空间，无中生有，排除；<br>C项，文段并未提及风速减弱属于人为因素，无中生有，排除；<br>D项，根据“中国科学院大气物理研究所开发的起沙模型很好地模拟出了2001年至2017年东亚沙尘暴频次的年际变化和减弱趋势，······从变化的原因来看，沙尘源区上地表风速减弱、植被覆盖增加、土壤变湿均起到了重要作用，贡献率分别为46%、30%、24%。可见风速减弱起主导作用，而植被覆盖增加和土壤变湿也有关键作用”可知，增加植被覆盖率能够减弱沙尘暴，当选。<br>故正确答案为D。<br>【文段出处】中国科学院《大气所等揭示近20年来东亚沙尘暴活动减弱的原因》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":40,"pid":"p52147c311e"},{"qid":"13504492","no":29,"type":"片段阅读","module":"言语理解与表达","stem":"<p>隐私计算作为一项可以实现数据在流转过程中“可用不可见”的技术，其价值被快速发掘并放大，成为数据安全、数据保护市场的关注焦点。隐私计算为解决数据存证、数据流通安全及隐私保护等问题提供了基础支撑，为海量复杂数据要素的全面流通提供了坚实的技术保障。这使隐私计算等技术成为驱动金融科技纵深发展的重要引擎。然而，隐私计算也面临着算力挑战。未来应重点探索隐私计算安全、性能、效果的平衡与统一，构建高安全、高效率、高可能的数据流通生态，实现隐私计算扩大应用落地范围，更好地推动数字经济发展。<br>这段文字未谈论隐私计算的：</p>","options":[{"k":"A","t":"应用前景"},{"k":"B","t":"技术保障"},{"k":"C","t":"发展难题"},{"k":"D","t":"发展方向"}],"answer":"B","multi":false,"explanation":"<p>A项，根据“隐私计算为解决数据存证、数据流通安全及隐私保护等问题提供了基础支撑······这使隐私计算等技术成为驱动金融科技纵深发展的重要引擎”可知，“应用前景”文段已谈论，排除；<br>B项，根据“隐私计算为解决数据存证、数据流通安全及隐私保护等问题提供了基础支撑，为海量复杂数据要素的全面流通提供了坚实的技术保障”可知，隐私计算是海量复杂数据要素全面流通的技术保障，但文段并未提及隐私计算的技术保障，无中生有，当选；<br>C项，根据“然而，隐私计算也面临着算力挑战”可知，“发展难题”文段已谈论，排除；<br>D项，根据“未来应重点探索隐私计算安全、性能、效果的平衡与统一······实现隐私计算扩大应用落地范围，更好地推动数字经济发展”可知，“发展方向”文段已谈论，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":41,"pid":"p52147c311e"},{"qid":"13504495","no":30,"type":"语句表达","module":"言语理解与表达","stem":"<p>①这种电池可以被用于驱动各种低功率、一次性可丢弃的电子器件<br>②加上一点水，纸带上的盐会溶解，释放出带电离子，这些离子在纸带上弥散激活电池组<br>③纸张和锌的生物可降解性，使这种电池能够最大程度减少可丢弃、低功率电子器件带来的环境影响<br>④纸带上分布着氯化钠，纸带较短端浸了蜡，含有石墨薄片的油墨印制在纸带一面，有锌粉的油墨印制在纸带的另一面<br>⑤一种新电池，主要由一个1平方厘米的电池单元组成，还包含3种印在长方形纸带上的油墨<br>⑥这种油墨将电池组正负极和两根电线连接起来，电线位于有蜡的那端<br>将以上6个句子重新排列，语序正确的是：</p>","options":[{"k":"A","t":"⑤①⑥④②③"},{"k":"B","t":"⑤③④⑥①②"},{"k":"C","t":"⑤④⑥②①③"},{"k":"D","t":"⑤⑥④③②①"}],"answer":"C","multi":false,"explanation":"<p>观察选项，首句均为⑤句，可通过对比⑤句之后的内容进行判断。⑤句引出“新电池”的话题，并介绍了其主要组成部分，包括1平方厘米的电池单元以及印在长方形纸带上的3种油墨，⑤句之后有①、③、④、⑥四个句子。①句介绍的是“这种电池”的功用范围，①句解题线索不明显；④句详细描述了纸带的物质分布情况，包括纸带较短端浸了蜡以及纸带两面分别印制有含石墨薄片和锌粉的油墨，而③句介绍了纸张和锌的生物可降解性对电池性能的影响，根据逻辑顺序，应先指出纸带上有“锌”再论述其具体作用，故④句在③句之前，排除B项；⑥句介绍的是油墨的功能及“电线位于有蜡的那端”，根据逻辑顺序，应先指出纸带上有油墨和蜡，之后再论述油墨的功能及与“蜡”相关内容，故④句在⑥句之前，排除A、D两项，锁定C项。<br>验证C项，⑤句引出话题，介绍新电池的组成部分，④⑥②三句对新电池组成部分及如何激活电池组作了介绍，①③两句对新电池的优势作了阐述，逻辑恰当，当选。<br>故正确答案为C。<br>【文段出处】光明网《加点水，激活纸电池》</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":42,"pid":"p52147c311e"},{"qid":"13504460","no":1,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/195997d2365a3d5.png\" class=\"fig\" style=\"width:500px;height:399px;\"></p>","options":[{"k":"A","t":"①④⑤，②③⑥"},{"k":"B","t":"①②⑥，③④⑤"},{"k":"C","t":"①④⑥，②③⑤"},{"k":"D","t":"①②⑤，③④⑥"}],"answer":"A","multi":false,"explanation":"<p>本题为分组分类题目。元素组成不同，且无明显属性规律，考虑数量规律。题干图形均由多个小元素组成，考虑元素的种类或个数。观察发现，图①④⑤中元素种类均为2，图②③⑥中元素种类均为1，即图①④⑤为一组，图②③⑥为一组。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":43,"pid":"p52147c311e"},{"qid":"13504515","no":2,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/19599c2ff9e7944.png\" class=\"fig\" style=\"width:600px;height:259px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成相同，考虑位置规律。观察第一组图形位置可知，从图一到图三，田字格中每一区域都是由前一幅图同位置顺时针旋转<img src=\"assets/img/gongshi/formula-baa9dcf22db28066.png\" class=\"tex\">得到，第二组应遵循相同的旋转规律，田字格中每一区域都是由前一幅图同位置顺时针旋转<img src=\"assets/img/gongshi/formula-baa9dcf22db28066.png\" class=\"tex\">得到，只有C项符合。</p><p>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":44,"pid":"p52147c311e"},{"qid":"12881897","no":3,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/1959a9ffd4682c4.png\" class=\"fig\" style=\"width:500px;height:395px;\"></p>","options":[{"k":"A","t":"①③④，②⑤⑥"},{"k":"B","t":"①②⑥，③④⑤"},{"k":"C","t":"①③⑤，②④⑥"},{"k":"D","t":"①④⑥，②③⑤"}],"answer":"B","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。题干图形出现“日”字变形图及出头端点，优先考虑笔画数。观察发现，图①②⑥均为2笔画图形，图③④⑤均为3笔画图形。即图①②⑥为一组，图③④⑤为一组。<br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":45,"pid":"p52147c311e"},{"qid":"12881896","no":4,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/1959a95a1d3eca0.png\" class=\"fig\" style=\"width:400px;height:472px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，优先考虑属性规律。观察发现，题干出现全直线、全曲线图形，考虑曲直性。九宫格优先看横行，第一行图形分别为全曲线图形、全直线图形、有曲有直图形；经验证，第二行符合此规律；第三行应用此规律，故“？”处图形应是有曲有直图形，只有D项符合。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":46,"pid":"p52147c311e"},{"qid":"13504506","no":5,"type":"图形推理","module":"判断推理","stem":"<p>下图左侧给定的是3×3×3的正方体被分解后的多面体，切去的部分可以由给定的①、②和③三个多面体组合而成。以下哪项能填入问号处？</p><p><img src=\"assets/img/timu/19599a9b27ea2f1.png\" class=\"fig\" style=\"width:600px;height:331px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查立体拼合。题干正方体中切去的部分可以由①、②以及B项三个多面体旋转后拼合而成，具体拼合过程如下图所示：</p><p><img src=\"assets/img/timu/19599aa491fecd5.png\" class=\"fig\" style=\"width:600px;height:402px;\"></p><p>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":47,"pid":"p52147c311e"},{"qid":"13504508","no":6,"type":"定义判断","module":"判断推理","stem":"<p>近零碳建筑是指建筑物通过适应气候特征和场地条件，最大幅度地降低建筑对能源的需求，运行过程中全电化，不使用燃气，建筑排放的碳量处于较低水平。近零碳建筑不仅利用各种方法减少自身产生的碳排放，还收集并利用雨水、太阳能等可再生能源，最终达到零废水、零能耗、零废弃物的理想状态。<br>下列做法不符合近零碳建筑理念的是：</p>","options":[{"k":"A","t":"加大物联网、大数据、人工智能等技术在建筑上的应用"},{"k":"B","t":"淘汰预制模块化建筑技术，采用传热系数高的幕墙建材"},{"k":"C","t":"实现建筑内空调精细化运行，始终保持温湿度的独立控制"},{"k":"D","t":"利用集成地源热泵、空气源热泵、光伏发电等可再生能源"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“建筑物通过适应气候特征和场地条件”、“最大幅度地降低建筑对能源的需求”、“运行过程中全电化，不使用燃气”、“建筑排放的碳量处于较低水平”、“利用雨水、太阳能等可再生能源”、“零废水、零能耗、零废弃物”。<br>第二步：逐一分析选项。<br>A项：加大物联网、大数据和人工智能技术在建筑上的应用，各项技术能够实现智能化识别、定位、跟踪、监管等功能，有利于能源管理和优化，符合“建筑物通过适应气候特征和场地条件”、“最大幅度地降低建筑对能源的需求”，符合定义，排除；<br>B项：建筑技术采用传热系数高的幕墙建材，会导致传热更快，保温隔热性能更差，反而增加建筑的能耗，不利于低碳，不符合“最大幅度地降低建筑对能源的需求”，不符合定义，当选；<br>C项：实现建筑内空调精细化运行，可以减少能源的消耗，符合“最大幅度地降低建筑对能源的需求”、“建筑排放的碳量处于较低水平”，符合定义，排除；<br>D项：利用集成地源热泵、空气源热泵、光伏发电等可再生能源，符合“建筑物通过适应气候特征和场地条件”、“利用雨水、太阳能等可再生能源”，符合定义，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":48,"pid":"p52147c311e"},{"qid":"13504507","no":7,"type":"定义判断","module":"判断推理","stem":"<p>马氏体相变是一种晶体结构变化。由于外界物理作用，比如温度、外力或者磁场的变化，一些材料的晶体结构会失去稳定性，原子发生短距离的移动，导致结构畸变。这种非原子扩散型的结构变化被称为马氏体相变。马氏体相变的一个重要特性是形状记忆效应，即基于两种结构相互转变和变体滑移，材料外形发生明显变化并能恢复原态。<br>根据上述定义，下列未体现马氏体相变的是：</p>","options":[{"k":"A","t":"将形状扭曲的别针放到热水里，别针立刻就能恢复原状"},{"k":"B","t":"起扩张血管作用的心脏支架用在外周血管时，因为挤压而变形"},{"k":"C","t":"通过电流加热控制合金网状结构变化，制造了能模仿蠕虫前进的机器人"},{"k":"D","t":"采用镍钛弓丝的牙齿矫形器受口腔温度影响，可产生形状恢复力，为牙齿矫形提供所需的力量"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“由于外界物理作用，比如温度、外力或者磁场的变化”、“材料外形发生明显变化并能恢复原态”。<br>第二步：逐一分析选项。<br>A项：形状扭曲的别针放到热水里，立刻就能恢复原状，说明由于温度的作用，别针的外形发生变化并恢复原状，符合“由于外界物理作用，比如温度、外力或者磁场的变化”、“材料外形发生明显变化并能恢复原态”，符合定义，排除；<br>B项：心脏支架因为挤压而变形，说明由于外力的作用，支架的外形发生变化，但未体现支架是否可以恢复原状，不符合“材料外形发生明显变化并能恢复原态”，不符合定义，当选；<br>C项：通过加热控制合金网状结构变化，制造了能模仿蠕虫前进的机器人，蠕虫的前进需要重复进行肢体的伸缩，说明由于温度的作用，机器人的外形发生变化并恢复原状，符合“由于外界物理作用，比如温度、外力或者磁场的变化”、“材料外形发生明显变化并能恢复原态”，符合定义，排除；<br>D项：镍钛弓丝的牙齿矫形器受口腔温度影响，可产生形状恢复力，说明由于温度的作用，牙齿矫形器的外形发生变化并恢复原状，符合“由于外界物理作用，比如温度、外力或者磁场的变化”、“材料外形发生明显变化并能恢复原态”，符合定义，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":49,"pid":"p52147c311e"},{"qid":"13504510","no":8,"type":"逻辑判断","module":"判断推理","stem":"<p>假定有一个理想化的纯黑体，它能将所有吸收的能量以“光”的形式释放，则称之为绝对黑体，它从绝对零度（单位为“K”即开尔文，<img src=\"assets/img/gongshi/formula-6ea511b8f4ac6e54.png\" class=\"tex\">）开始被加热升温会由黑变为发红光、黄光、白光、蓝光。加热到N（K）时，绝对黑体发光所含的光谱成分就称N（K）色温；某发光物与N（K）温度下绝对黑体发光所含的光谱成分相同，就称其色温为N（K）。</p><p>以下关于色温的叙述正确的是：</p>","options":[{"k":"A","t":"<p>把红、黄划分为暖色调，白、蓝划分为冷色调是由色温而来的</p>"},{"k":"B","t":"<p>一天内，肉眼看到的太阳颜色的变化是温差引起的色温变化导致的</p>"},{"k":"C","t":"<p>某发光体的光谱成分与绝对黑体在<img src=\"assets/img/gongshi/formula-4ce7f9fb56ea07b5.png\" class=\"tex\">时的相同，则它的色温是3000K</p>"},{"k":"D","t":"<p>某灯光的色温是1000K，则与之光谱成分相同的绝对黑体温度是<img src=\"assets/img/gongshi/formula-0116d0cddeb55504.png\" class=\"tex\"></p>"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。</p><p>绝对黑体：“能将所有吸收的能量以‘光’的形式释放”；</p><p>色温：“从绝对零度（单位为‘K’即开尔文，<img src=\"assets/img/gongshi/formula-6ea511b8f4ac6e54.png\" class=\"tex\">）开始被加热升温会由黑变为发红光、黄光、白光、蓝光”、“加热到N（K）时，绝对黑体发光所含的光谱成分就称N（K）色温”、“发光物与N（K）温度下绝对黑体发光所含的光谱成分相同”。</p><p>第二步：逐一分析选项。</p><p>A项：根据“从绝对零度开始被加热升温会由黑变为发红光、黄光、白光、蓝光”可以推出光的颜色与温度有关，但是并不能由此推出色温是否是划分冷、暖色调的依据，说法错误，排除；</p><p>B项：根据“从绝对零度开始被加热升温会由黑变为发红光、黄光、白光、蓝光”可知光的颜色与温度有关，但是选项并未提及一天内太阳具体的温差变化，实际上一天内太阳颜色的变化主要是由于大气散射引起的，并非色温变化导致，说法错误，排除；</p><p>C项：根据“从绝对零度（单位为‘K’即开尔文，<img src=\"assets/img/gongshi/formula-6ea511b8f4ac6e54.png\" class=\"tex\">）开始被加热升温会由黑变为发红光、黄光、白光、蓝光”、“发光物与N（K）温度下绝对黑体发光所含的光谱成分相同”，因此可知N（K）就是绝对黑体从<img src=\"assets/img/gongshi/formula-51955a3ec09556ad.png\" class=\"tex\">加热到有光的色温，发光物和绝对黑体光谱相同时色温就是N（K），二者的换算关系为：<img src=\"assets/img/gongshi/formula-42dff18b1f05226b.png\" class=\"tex\">，因此，某发光体相同的绝对温度在<img src=\"assets/img/gongshi/formula-4ce7f9fb56ea07b5.png\" class=\"tex\">时，对应的色温为<img src=\"assets/img/gongshi/formula-523ab5a38a6035cc.png\" class=\"tex\">，说法正确，当选；</p><p>D项：根据“从绝对零度（单位为‘K’即开尔文，<img src=\"assets/img/gongshi/formula-6ea511b8f4ac6e54.png\" class=\"tex\">）开始被加热升温会由黑变为发红光、黄光、白光、蓝光”、“发光物与N（K）温度下绝对黑体发光所含的光谱成分相同”，因此可知N（K）就是绝对黑体从<img src=\"assets/img/gongshi/formula-51955a3ec09556ad.png\" class=\"tex\">加热到有光的色温，发光物和绝对黑体光谱相同时色温就是N（K），二者的换算关系为：<img src=\"assets/img/gongshi/formula-57546e3bea22e986.png\" class=\"tex\">，某灯光的色温是1000K，则与之光谱成分相同的绝对黑体温度<img src=\"assets/img/gongshi/formula-01fa06cea2439ca4.png\" class=\"tex\">，并非<img src=\"assets/img/gongshi/formula-0116d0cddeb55504.png\" class=\"tex\">，说法错误，排除。</p><p>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":50,"pid":"p52147c311e"},{"qid":"13504484","no":9,"type":"逻辑判断","module":"判断推理","stem":"<p>在某个定义域上有加减乘除等多种二元运算（用★代表其中一种），如果在定义域内存在一个数w，对于定义域范围内的每个数m（包括w），都有w★m=m，则称w为该种二元运算上的左幺元。<br>以下关于左幺元的叙述正确的是：</p>","options":[{"k":"A","t":"在整数范围内的乘法运算中，1是左幺元"},{"k":"B","t":"在整数范围内的加法运算中，1是左幺元"},{"k":"C","t":"在整数范围内的减法运算中，0是左幺元"},{"k":"D","t":"在整数范围内的除法运算中，0是左幺元"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“如果w，对于定义域范围内的每个数m（包括w），都有w★m=m”。<br>第二步：逐一分析选项。<br>A项：1乘以任何整数都等于原来的数，符合“如果w，对于定义域范围内的每个数m（包括w），都有w★m=m”，符合定义，当选；<br>B项：1加任何整数都不等于原来的数，不符合“如果w，对于定义域范围内的每个数m（包括w），都有w★m=m”，不符合定义，排除；<br>C项：0减去除0外的任何整数都不等于原来的数，不符合“如果w，对于定义域范围内的每个数m（包括w），都有w★m=m”，不符合定义，排除；<br>D项：0除以除0外的任何整数都不等于原来的数，不符合“如果w，对于定义域范围内的每个数m（包括w），都有w★m=m”，不符合定义，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":51,"pid":"p52147c311e"},{"qid":"13504474","no":10,"type":"定义判断","module":"判断推理","stem":"<p>物质循环是指在生态系统中，各种元素物质沿着特定途径从周围环境中被生物体吸收利用，再从生物体回到周围环境的循环变化过程，即各种元素物质在生物体和非生物环境之间的往复循环运转过程。<br>下列诗句中所描写的内容最能体现物质循环的是：</p>","options":[{"k":"A","t":"时有落花至，远随流水香"},{"k":"B","t":"莫作绕山云，循环无定期"},{"k":"C","t":"黄河之水天上来，奔流到海不复回"},{"k":"D","t":"落红不是无情物，化作春泥更护花"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“各种元素物质”、“在生物体和非生物环境之间”、“往复循环运转”。<br>第二步：逐一分析选项。<br>A项：选项意思是：不时有落花随溪水飘流而至，远远地就可闻到水中的芳香。表明落花及其香味在非生物环境中运转，但未提及生物体环境，不符合“在生物体和非生物环境之间”，不符合定义，排除；<br>B项：选项意思是：不要像绕山云般循环往复，没有固定的周期。表明云在非生物环境中循环运转，但未提及生物体环境，不符合“在生物体和非生物环境之间”，不符合定义，排除；<br>C项：选项意思是：那黄河之水犹如从天上倾泻而来，波涛翻滚直奔大海从来不会再往回流。表明黄河水在非生物环境中流动，但未提及生物体环境，且流动过程不是往复循环的，不符合“在生物体和非生物环境之间”、“往复循环运转”，不符合定义，排除；<br>D项：选项意思是：从枝头上掉下来的落花不是无情之物，即使化作春泥，也甘愿化作养料，滋养美丽的春花成长。表明落花的元素物质在生物体和非生物环境之间运转，符合“各种元素物质”、“在生物体和非生物环境之间”、“往复循环运转”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":52,"pid":"p52147c311e"},{"qid":"12881898","no":11,"type":"定义判断","module":"判断推理","stem":"<p>印客也称in客，指的是把自己在网络平台上所写的、画的、摘录的任何文字和图片整理成册，自己制作或请人制作成具有保存价值并体现个性的印刷品的人。<br>根据以上定义，下列属于印客的是：</p>","options":[{"k":"A","t":"小楠是某大学的特聘教师，撰写不少高水平学术文章，去年她将这些文章分类整理成册，目前正与出版社商量印刷排版事宜"},{"k":"B","t":"小雪是某印刷服务社的美工，具备较高专业素养，业务内容是美化处理客户发来的图片和文字，成品在网络上得到海量好评"},{"k":"C","t":"小影是某网站的专栏作家，在网络上发表多篇高阅读量和点赞量的文章，不少读者将她的文章打印出来，作为范本交流学习"},{"k":"D","t":"小芳是某企业员工，经常在微博上用图片加文字的形式表达心灵感悟，她定期收集这些记录，请专业人士排版设计印刷成册"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“把自己在网络平台上所写的、画的、摘录的任何文字和图片整理成册”、“自己制作或请人制作成印刷品”。<br>第二步：逐一分析选项。<br>A项：大学教师小楠将撰写的学术文章整理成册并准备印刷，但没有体现这些学术文章是在网络平台上写的，不符合“把自己在网络平台上所写的、画的、摘录的任何文字和图片整理成册”，不符合定义，排除；<br>B项：小雪是美化处理“客户”发来的图片和文字，并非是“自己”在网上写、画或摘录的文字和图片，不符合“把自己在网络平台上所写的、画的、摘录的任何文字和图片整理成册”，不符合定义，排除；<br>C项：读者将小影在网络平台上写的文章打印出来，并非小影自己将这些文章打印出来，也未体现小影请读者打印，不符合“自己制作或请人制作成印刷品”，不符合定义，排除；<br>D项：小芳定期收集自己在微博上用图片加文字所表达出来的内容，并请专业人士印刷成册，符合“把自己在网络平台上所写的、画的、摘录的任何文字和图片整理成册”、“自己制作或请人制作成印刷品”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":53,"pid":"p52147c311e"},{"qid":"13504502","no":12,"type":"定义判断","module":"判断推理","stem":"<p>拓扑绝缘体是一种内部绝缘、界面允许电荷移动的材料，在拓扑绝缘体的内部，电子能带结构和常规的绝缘体相似，但在其表面或边界上存在特殊的量子态，这些量子态位于块体能带结构的带隙之中，从而能够导电。<br>根据上述定义，以下哪项是拓扑绝缘体?</p>","options":[{"k":"A","t":"量子点接触是一种纳米尺度的电子器件，其整体的导电性质可以通过调整器件的尺寸和形状来调控"},{"k":"B","t":"氮化镓中由半导体异质结中的特殊电子结构形成的二维电子气，虽然其并不是一种材料，但在一定条件下能够导电"},{"k":"C","t":"纯石墨烯本身不导电，但是经过一些工艺加工后，会表现出在一定条件下可以允许表面电荷移动形成导电能力的一种量子效应"},{"k":"D","t":"镧钡铜氧体系的超导陶瓷，是一类在临界温度时电阻为零的陶瓷材料，它还表现出完全抗磁性的行为，在传输过程中几乎没有能量消耗"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“内部绝缘、界面允许电荷移动的材料”。<br>第二步：逐一分析选项。<br>A项：量子点接触可以通过调整器件的尺寸和形状来调控整体的导电性，未提及其内部和外部的导电情况，不符合“内部绝缘、界面允许电荷移动的材料”，不符合定义，排除；<br>B项：氮化镓中的二维电子气在一定条件下能够导电，不符合“内部绝缘、界面允许电荷移动的材料”，不符合定义，排除；<br>C项：纯石墨烯本身不导电，符合“内部绝缘”，经过一些工艺加工后可以允许表面电荷移动形成导电能力，符合“界面允许电荷移动”，符合定义，当选；<br>D项：镧钡铜氧体系的超导陶瓷是一类在临界温度时电阻为零的陶瓷材料，没有提及其导电性，不符合“内部绝缘、界面允许电荷移动的材料”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":54,"pid":"p52147c311e"},{"qid":"13504511","no":13,"type":"定义判断","module":"判断推理","stem":"<p>计算亲属关系亲疏远近的单位是亲等，国际最为通用的是罗马法亲等计算法和寺院法亲等计算法，二者关于旁系血亲的计算法有所不同：罗马法亲等计算法是从己身往上数至双方共同的直系血亲即同源人，每经一代为一亲等，再往下数至要计算的人，也是每经一代为一亲等，所有数字相加就是双方之间的亲等数；寺院法亲等计算法是从己身和所要计算的人分别往上数至血缘同源人，两边的亲等数相等时，就采用一边的亲等数，如果亲等数不等，则采用多的一方的亲等数。<br>根据上述定义，下列符合罗马法亲等计算法的是：</p>","options":[{"k":"A","t":"自己与外甥的女儿之间的亲等是三亲等"},{"k":"B","t":"表妹与堂妹之间的亲等，都是四亲等"},{"k":"C","t":"姑侄之间的亲等是二亲等"},{"k":"D","t":"自己与伯父之间是三亲等"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。</p><p>罗马法亲等计算法：“从己身往上数至双方共同的直系血亲即同源人，每经一代为一亲等”、“再往下数至要计算的人，也是每经一代为一亲等”、“所有数字相加”；</p><p>寺院法亲等计算法：“从己身和所要计算的人分别往上数至血缘同源人”、“两边的亲等数相等时，就采用一边的亲等数”、“亲等数不等，则采用多的一方的亲等数”。</p><p>第二步：逐一分析选项。</p><p>A项：自己与外甥的女儿的同源人是自己的父母，从自己到父母经过“自己<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">父母”，共1代，从父母到外甥的女儿经过“父母<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">姐姐/妹妹<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">外甥<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">外甥的女儿”，共3代，1+3=4，因此为四亲等，不符合定义，排除；</p><p>B项：当表妹为妈妈的兄弟姐妹的女儿时，与堂妹（父亲的兄弟的女儿）没有共同的直系血亲，无血缘关系和亲等关系，不符合定义，排除；</p><p>C项：姑姑和侄子的同源人是侄子的爷爷，从姑姑到侄子的爷爷经过“姑姑<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">爷爷”，共1代，从爷爷到侄子经过“爷爷<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">父亲<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">侄子”，共2代，1+2=3，因此为三亲等，不符合定义，排除；</p><p>D项：自己与伯父的同源人是自己的爷爷，从自己到爷爷经过“自己<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">父亲<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">爷爷”，共2代，从爷爷到伯父经过“爷爷<img src=\"assets/img/gongshi/formula-c81dec104c0a9a65.png\" class=\"tex\">伯父”，共1代，2+1=3，因此为三亲等，符合定义，当选。</p><p>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":55,"pid":"p52147c311e"},{"qid":"13504455","no":14,"type":"定义判断","module":"判断推理","stem":"<p>免疫电镜技术是将抗原抗体反应的特异性和电子显微镜的高分辨率相结合，在亚细胞和超微结构水平上对抗原进行定位分析的一种高精确度的技术。<br>根据上述定义，下列不属于免疫电镜技术的是：</p>","options":[{"k":"A","t":"酶的催化作用对其底物的反应可形成不同的电子密度，运用电子显微镜来观察，可确定酶的存在，从而对抗原进行定位"},{"k":"B","t":"胶体金与铁蛋白一样具有高电子密度，将沙门氏菌的抗血清与胶体金颗粒结合，可以明确病原物抗原在电镜水平的定位"},{"k":"C","t":"铁蛋白通过交联剂与抗体等物质的共价结合，其分辨率高、散射能力强，借助电镜可以准确描述抗原抗体复合物的定位"},{"k":"D","t":"微流体检测芯片中的免疫电极体系有镀金基层、导电聚合物层和抗体层，三者自下而上依次贴合，提高检测定位的水平"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“将抗原抗体反应的特异性和电子显微镜的高分辨率相结合”、“在亚细胞和超微结构水平上对抗原进行定位分析”。<br>第二步：逐一分析选项。<br>A项：该项中运用电子显微镜观察酶的催化作用，符合“将抗原抗体反应的特异性和电子显微镜的高分辨率相结合”，通过确定酶的存在来对抗原进行定位，符合“在亚细胞和超微结构水平上对抗原进行定位分析”，符合定义，排除；<br>B项：该项中将沙门氏菌的抗血清与胶体金颗粒结合，利用电子显微镜明确抗原定位，符合“将抗原抗体反应的特异性和电子显微镜的高分辨率相结合”、“在亚细胞和超微结构水平上对抗原进行定位分析”，符合定义，排除；<br>C项：该项中铁蛋白通过交联剂与抗体等物质的共价结合，借助电镜准确描述抗原抗体复合物的定位，符合“将抗原抗体反应的特异性和电子显微镜的高分辨率相结合”、“在亚细胞和超微结构水平上对抗原进行定位分析”，符合定义，排除；<br>D项：该项中只是提到微流体检测芯片中的免疫电极体系有不同的层结构来提高检测定位水平，但没有提及使用电子显微镜，不符合“将抗原抗体反应的特异性和电子显微镜的高分辨率相结合”，不符合定义，当选。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":56,"pid":"p52147c311e"},{"qid":"13504472","no":15,"type":"定义判断","module":"判断推理","stem":"<p>意思主义和表示主义是解释确定语言含义的两种方法。当语言发生歧义时，意思主义认为应当按照言语者内心所欲表达的真实意思来确定语言含义，而无需在意别人如何理解；反之，表示主义主张语言一旦表达出来便与言语者没有关系了，应当按照社会公众的通常理解来确定语言的含义。<br>根据上述定义，下列说法最能体现意思主义的是：</p>","options":[{"k":"A","t":"误载不害真意"},{"k":"B","t":"人同此心，心同此理"},{"k":"C","t":"一千个读者有一千个哈姆雷特"},{"k":"D","t":"横看成岭侧成峰，远近高低各不同"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>意思主义：“按照言语者内心所欲表达的真实意思来确定语言含义”；<br>表示主义：“按照社会公众的通常理解来确定语言的含义”。<br>第二步：逐一分析选项。<br>A项：“误载不害真意”指表意人与相对人已达成意思表示一致，不因合同文本中出现的用词错误而影响双方已经达成的真实合意，强调要按照表意人（言语者）内心真实的意思来确定，符合“按照言语者内心所欲表达的真实意思来确定语言含义”，符合“意思主义”定义，当选；<br>B项：“人同此心，心同此理”的意思是合情合理的事，大家想法都会相同，不符合“按照言语者内心所欲表达的真实意思来确定语言含义”，不符合“意思主义”定义，排除；<br>C项：“一千个读者有一千个哈姆雷特”指人们对同一艺术作品的解读因个体差异而呈现多样性，不符合“按照言语者内心所欲表达的真实意思来确定语言含义”，不符合“意思主义”定义，排除；<br>D项：“横看成岭侧成峰，远近高低各不同”的意思是从正面、侧面看庐山山岭连绵起伏、山峰耸立，从远处、近处、高处、低处看庐山，庐山呈现各种不同的样子，不符合“按照言语者内心所欲表达的真实意思来确定语言含义”，不符合“意思主义”定义，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":57,"pid":"p52147c311e"},{"qid":"13504453","no":16,"type":"类比推理","module":"判断推理","stem":"<p>言之无文：行之不远</p>","options":[{"k":"A","t":"一叶障目：不见泰山"},{"k":"B","t":"宁为玉碎：不为瓦全"},{"k":"C","t":"藏诸名山：传之其人"},{"k":"D","t":"取之不尽：用之不竭"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“言之无文，行之不远”的意思是说话没有文采，就传播不远，因为“言之无文”，所以“行之不远”，二者为因果关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“一叶障目，不见泰山”的意思是一片树叶挡住了眼睛，连面前高大的泰山都看不见，因为“一叶障目”，所以“不见泰山”，二者为因果关系，与题干逻辑关系一致，当选；<br>B项：“宁为玉碎，不为瓦全”的意思是指宁愿做高贵的玉器而破碎，也不愿做低贱的瓦器得以保全，二者不是因果关系，与题干逻辑关系不一致，排除；<br>C项：“藏诸名山，传之其人”的意思是指把著作藏在名山，传给后来志趣相投的人，二者不是因果关系，与题干逻辑关系不一致，排除；<br>D项：“取之不尽，用之不竭”的意思是指拿不完用不尽，二者为并列关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":58,"pid":"p52147c311e"},{"qid":"12882052","no":17,"type":"类比推理","module":"判断推理","stem":"<p>柠檬水：酸梅汤</p>","options":[{"k":"A","t":"橘子汁：香蕉水"},{"k":"B","t":"梅子酒：葡萄干"},{"k":"C","t":"苹果派：草莓挞"},{"k":"D","t":"西瓜霜：荔枝蜜"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“柠檬水”和“酸梅汤”是两种不同的饮品，二者为并列关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“橘子汁”是橘子压榨出的汁水，“香蕉水”是由多种有机溶剂混合而成的无色透明液体，因具香蕉气味而得名，二者不是并列关系，与题干逻辑关系不一致，排除；<br>B项：“梅子酒”是将梅子放置于米类蒸馏酒里长时间浸泡入味的一种浸泡酒，“葡萄干”是借助于太阳热或人工加热使葡萄果实脱水形成的固态食品，二者不是并列关系，与题干逻辑关系不一致，排除；<br>C项：“苹果派”是以苹果、面粉、黄油等为原材料加工而成的一种甜点，“草莓挞”是以草莓、面粉、黄油、糖、牛奶等为原材料制作的一种甜品，二者为并列关系，与题干逻辑关系一致，当选；<br>D项：“西瓜霜”是西瓜的成熟果实与芒硝经加工而成的白色结晶粉末，也是一种中药，“荔枝蜜”是采用荔枝的花而酿制的蜂蜜，是南方地区生产的上等蜂蜜，带有清淡的荔枝花香味，二者不是并列关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":59,"pid":"p52147c311e"},{"qid":"13504429","no":18,"type":"类比推理","module":"判断推理","stem":"<p>低碳排放：保护环境</p>","options":[{"k":"A","t":"候鸟迁徙：气候变化"},{"k":"B","t":"昆虫叮咬：过敏反应"},{"k":"C","t":"收集数据：调查研究"},{"k":"D","t":"滴水成冰：热胀冷缩"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>低碳排放是为了保护环境，二者为方式目的的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：候鸟迁徙是因为气候变化，二者为因果的对应关系，与题干逻辑关系不一致，排除；<br>B项：昆虫叮咬会导致过敏反应，二者为因果的对应关系，与题干逻辑关系不一致，排除；<br>C项：收集数据是为了调查研究，二者为方式目的的对应关系，与题干逻辑关系一致，当选；<br>D项：滴水成冰意思是水滴下去就结成冰，形容天气十分寒冷；热胀冷缩指物体受热时会膨胀，遇冷时会收缩的特性，二者不是方式目的的对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":60,"pid":"p52147c311e"},{"qid":"12882053","no":19,"type":"类比推理","module":"判断推理","stem":"<p>石料：木材：印章</p>","options":[{"k":"A","t":"毛笔：墨水：书法"},{"k":"B","t":"湘绣：蜀绣：刺绣"},{"k":"C","t":"宣纸：年画：国画"},{"k":"D","t":"搪瓷：塑料：脸盆"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>石料和木材均可以用来制作印章，前两词为并列关系，分别与第三词构成原材料与成品的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：毛笔和墨水配套使用可以用来书写书法作品，前两词为配套使用的对应关系，第一词与第三词也不是原材料与成品的对应关系，与题干逻辑关系不一致，排除；<br>B项：湘绣和蜀绣是中国刺绣中两个不同的门类，前两词为并列关系，分别与第三词构成种属关系，与题干逻辑关系不一致，排除；<br>C项：绘制年画和国画会用到宣纸，前两词不是并列关系，第二词与第三词也不是原材料与成品的对应关系，与题干逻辑关系不一致，排除；<br>D项：搪瓷和塑料均可以用来制作脸盆，前两词为并列关系，分别与第三词构成原材料与成品的对应关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":61,"pid":"p52147c311e"},{"qid":"12882054","no":20,"type":"类比推理","module":"判断推理","stem":"<p>衰弱：噪声：听力</p>","options":[{"k":"A","t":"锻炼：饮食：健康"},{"k":"B","t":"杠杆：重力：质量"},{"k":"C","t":"降低：摩擦：速度"},{"k":"D","t":"气候变暖：冰层融化：环境"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>噪声会导致听力衰弱，且噪声是原因，听力衰弱是结果，听力衰弱构成主谓结构。<br>第二步：判断选项词语间逻辑关系。<br>A项：饮食不会导致健康锻炼，且饮食不是原因，与题干逻辑关系不一致，排除；<br>B项：重力是地球对物体的吸引力，物体的质量越大，重力越大，重力不是原因，与题干逻辑关系不一致，排除；<br>C项：摩擦会导致速度降低，且摩擦是原因，速度降低是结果，速度降低构成主谓结构，与题干逻辑关系一致，当选；<br>D项：气候变暖会导致冰层融化，进一步会影响环境，冰层融化是结果，而非原因，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":62,"pid":"p52147c311e"},{"qid":"13504485","no":21,"type":"类比推理","module":"判断推理","stem":"<p>车辆：货车：运输</p>","options":[{"k":"A","t":"温室气体：甲烷：二氧化碳"},{"k":"B","t":"未来产业：量子信息：研究监管"},{"k":"C","t":"自我意识：人格：心理调节"},{"k":"D","t":"绿色能源：太阳能：发电"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>货车是一种车辆，前两词为种属关系，货车可以用来运输，后两词为功能对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：甲烷和二氧化碳均是一种温室气体，第一词与后两词分别构成种属关系，且后两词为并列关系，与题干逻辑关系不一致，排除；<br>B项：量子信息是一种未来产业，前两词为种属关系，研究监管不是量子信息的功能，后两词不是功能对应关系，与题干逻辑关系不一致，排除；<br>C项：自我意识对人格的形成、发展有作用，前两词不是种属关系，心理调节不是人格的功能，后两词不是功能对应关系，与题干逻辑关系不一致，排除；<br>D项：太阳能是一种绿色能源，前两词为种属关系，太阳能可以用来发电，后两词为功能对应关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":63,"pid":"p52147c311e"},{"qid":"12881899","no":22,"type":"类比推理","module":"判断推理","stem":"<p>名垂青史：光耀千秋：光前裕后</p>","options":[{"k":"A","t":"畏首畏尾：犹犹豫豫：瞻前顾后"},{"k":"B","t":"投鼠忌器：缩手缩脚：慎终追远"},{"k":"C","t":"光宗耀祖：光耀门楣：落叶归根"},{"k":"D","t":"空前绝后：开天辟地：继往开来"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“名垂青史”意思是好的名声和事迹载入史籍永远流传；“光耀千秋”意思是光辉照耀千年，形容功绩或荣耀长久流传，影响深远；“光前裕后”意思是给前人增光，为后代造福，多用来称颂他人功业隆盛。三者为近义关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“畏首畏尾”形容疑虑过多；“犹犹豫豫”形容拿不定主意；“瞻前顾后”意思是看看前面再看看后面，形容做事以前考虑周密谨慎，也指顾虑太多，犹豫不定。三者为近义关系，与题干逻辑关系一致，当选；<br>B项：“投鼠忌器”意思是要打老鼠又怕打坏了旁边的器物，比喻想打击坏人而又有所顾忌；“缩手缩脚”意思是因寒冷而四肢不能舒展的样子，也形容做事胆小，顾虑多，不敢放手；“慎终追远”旧指慎重地办理父母丧事，虔诚地祭祀远代祖先，后也指谨慎从事，追念前贤。第三个词与前两个词不是近义关系，与题干逻辑关系不一致，排除；<br>C项：“光宗耀祖”意思是为祖先、宗族增添光彩；“光耀门楣”意思是做出了让家门荣耀的事情；“落叶归根”比喻事物有一定的归宿，多指客居他乡的人终要回到本乡。第三个词与前两个词不是近义关系，与题干逻辑关系不一致，排除；<br>D项：“空前绝后”意思是从前没有过，以后也不会有，多用来形容非凡的成就或盛况；“开天辟地”比喻空前的，自古以来没有过的；“继往开来”意思是继承前人的事业，并为将来开辟道路。三者不是近义关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"p52147c311e"},{"qid":"12881900","no":23,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 众志成城 相当于 拒谏饰非 对于 （    ）</p>","options":[{"k":"A","t":"孤掌难鸣 广开言路"},{"k":"B","t":"寸积铢累 从谏如流"},{"k":"C","t":"众擎易举 集思广益"},{"k":"D","t":"独木难支 闭目塞听"}],"answer":"A","multi":false,"explanation":"<p>逐一代入选项。<br>A项：孤掌难鸣指一个巴掌拍不响，比喻孤立无助，不能成事，众志成城指大家齐心协力，就像城墙一样地牢固，比喻众人团结一致，就能克服困难，二者为反义关系；拒谏饰非指拒绝规劝，掩饰错误或过失，广开言路指尽可能地让人们广泛发表意见，博采众议，二者为反义关系，前后逻辑关系一致，当选；<br>B项：寸积铢累指由很小的数量一点一滴地慢慢积累起来，众志成城指大家齐心协力，就像城墙一样地牢固，比喻众人团结一致，就能克服困难，二者无明显逻辑关系；拒谏饰非指拒绝规劝，掩饰错误或过失，从谏如流指听从善意的规劝，就像水从高处流下一样顺畅，形容乐意接受别人意见，二者为反义关系，前后逻辑关系不一致，排除；<br>C项：众擎易举指许多人一齐用力，容易把东西举起来，比喻大家同心协力就容易把事情办成，众志成城指大家齐心协力，就像城墙一样地牢固，比喻众人团结一致，就能克服困难，二者为近义关系；拒谏饰非指拒绝规劝，掩饰错误或过失，集思广益指集中群众的智慧，广泛吸收有益的意见，二者为反义关系，前后逻辑关系不一致，排除；<br>D项：独木难支指一根木头支持不住高大的房子，比喻一个人的力量难以支撑全局，也比喻艰巨的任务不是一个人所能胜任的，众志成城指大家齐心协力，就像城墙一样地牢固，比喻众人团结一致，就能克服困难，二者为反义关系；拒谏饰非指拒绝规劝，掩饰错误或过失，闭目塞听指闭着眼睛，堵住耳朵，形容对外界事物不闻不问或不了解，二者为近义关系，前后逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":65,"pid":"p52147c311e"},{"qid":"12882055","no":24,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 松树 相当于 CPU 对于 （    ）</p>","options":[{"k":"A","t":"松果  显卡"},{"k":"B","t":"植物  电器"},{"k":"C","t":"松子  电脑"},{"k":"D","t":"松茸  芯片"}],"answer":"C","multi":false,"explanation":"<p>逐一代入选项。<br>A项：松果是松树的组成部分，二者为组成关系；CPU和显卡均为电脑的部件，二者为并列关系，前后逻辑关系不一致，排除；<br>B项：松树是植物，二者为种属关系；CPU不是电器，二者不是种属关系，前后逻辑关系不一致，排除；<br>C项：松子是松树的组成部分，二者为组成关系；CPU是电脑的组成部分，二者为组成关系，前后逻辑关系一致，当选；<br>D项：松茸是一种真菌，通常生长在松树根部附近，二者为共生关系；CPU是一种芯片，二者为种属关系，前后逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":66,"pid":"p52147c311e"},{"qid":"12882056","no":25,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 运动器材 相当于 玫瑰 对于 （    ）</p>","options":[{"k":"A","t":"单杠  爱情"},{"k":"B","t":"哑铃  花卉"},{"k":"C","t":"健身  精油"},{"k":"D","t":"铸铁  月季"}],"answer":"B","multi":false,"explanation":"<p>逐一代入选项。<br>A项：单杠是一种运动器材，二者是种属关系；玫瑰可象征爱情，二者是比喻象征关系，前后逻辑关系不一致，排除；<br>B项：哑铃是一种运动器材，二者是种属关系；玫瑰是一种花卉，二者也是种属关系，前后逻辑关系一致，当选；<br>C项：运动器材有健身的作用，二者是功能的对应关系；玫瑰是制作精油的一种原材料，二者是原材料与成品的对应关系，前后逻辑关系不一致，排除；<br>D项：‌铸铁是制作运动器材的一种原材料‌，二者是原材料与成品的对应关系；玫瑰和月季是同属蔷薇科的两种不同花卉，二者是反对关系，前后逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":67,"pid":"p52147c311e"},{"qid":"13504487","no":26,"type":"逻辑判断","module":"判断推理","stem":"<p>有研究人员针对素食对心血管疾病高危人群的影响进行数据分析发现，素食与低密度脂蛋白胆固醇、葡萄糖水平和体重的显著改善有关，因此，研究人员提出素食可有效降低胆固醇、血糖和体重。<br>以下哪项如果为真，不能削弱上述结论：</p>","options":[{"k":"A","t":"快餐店素食套餐含有精制碳水化合物、蔗糖、玉米糖浆等，热量更高"},{"k":"B","t":"部分素食含有大量反式脂肪酸，反式脂肪酸的摄入会引起胆固醇升高"},{"k":"C","t":"广义上的素食不仅包括蔬菜等纯素食，还包括鸡蛋、奶和乳制品"},{"k":"D","t":"素食中的蔬菜多是油炸的，这使素食者变胖的风险更大"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：素食可有效降低胆固醇、血糖和体重。<br>论据：素食与低密度脂蛋白胆固醇、葡萄糖水平和体重的显著改善有关。<br>本题论点和论据讨论的均是“素食”和“胆固醇、血糖和体重”的关系，二者话题一致，且本题为选非题，排除能够削弱的选项即可。<br>第二步：逐一分析选项。<br>A项：选项指出“快餐店素食套餐含有精制碳水化合物、蔗糖、玉米糖浆等，热量更高”，说明素食可能无法降低血糖和体重，削弱论点，可以削弱，排除；<br>B项：选项指出“部分素食含有大量反式脂肪酸，反式脂肪酸的摄入会引起胆固醇升高”，说明素食无法降低胆固醇，削弱论点，可以削弱，排除；<br>C项：选项指出“广义上的素食”包含哪些，但并未说明素食是否能够“有效降低胆固醇、血糖和体重”，话题不一致，为无关项，无法削弱，当选；<br>D项：选项指出“素食中的蔬菜多是油炸的，这使素食者变胖的风险更大”，说明素食无法降低体重，削弱论点，可以削弱，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":68,"pid":"p52147c311e"},{"qid":"13504491","no":27,"type":"逻辑判断","module":"判断推理","stem":"<p>某研究团队发布了一项关于睡眠习惯、时间与癌症风险的研究。研究分析了近1.5万人，发现睡眠时间短导致癌症风险升高，和睡眠时间为6-8小时的参与者相比，夜间睡眠时间少于6小时的人，患癌风险升高41%，和午睡时间多于60分钟的参与者相比，从不午睡的参与者患癌风险升高60%。<br>以下哪项如果为真，最能加强上述观点：</p>","options":[{"k":"A","t":"睡眠时间短会损害免疫功能、降低人体对肿瘤细胞的识别和消灭能力"},{"k":"B","t":"人类环境、卫生资源和睡眠习惯的变化，导致癌症发病原因发生了变化"},{"k":"C","t":"夜间睡眠时间短或不午睡的参与者，大多年龄较大且缺少锻炼，健康状况不佳"},{"k":"D","t":"和总睡眠时间为7-8小时的参与者相比，总睡眠时间少于7小时的男性，患癌风险升高69%"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：睡眠时间短导致癌症风险升高。<br>论据：和睡眠时间为6-8小时的参与者相比，夜间睡眠时间少于6小时的人，患癌风险升高41%，和午睡时间多于60分钟的参与者相比，从不午睡的参与者患癌风险升高60%。<br>论据在说夜间睡眠时间短和从不午睡的参与者患癌风险高，论点在说睡眠时间短导致癌症风险升高，二者话题一致，加强考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项指出“睡眠时间短会损害免疫功能、降低人体对肿瘤细胞的识别和消灭能力”，解释了睡眠时间短与患癌风险高之间的关系，补充论据，可以加强，保留；<br>B项：该项指出人类环境、卫生资源和睡眠习惯的变化使得癌症发病原因发生了变化，并未说明睡眠时间短和癌症风险高有关系，无法加强，排除；<br>C项：该项指出夜间睡眠时间短或不午睡的参与者，年龄较大且缺少锻炼，但并未说明年龄较大、缺少锻炼是否癌症风险就会高，为不明确项，无法加强，排除；<br>D项：该项指出睡眠时间短于7小时的男性患癌风险升高了69%，举例说明睡眠时间短与患癌风险高之间存在关系，补充论据，可以加强，保留。<br>比较A、D两项，A项是解释原因，D项举例，解释原因的加强力度大于举例，A项的加强力度更强。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":69,"pid":"p52147c311e"},{"qid":"13504516","no":28,"type":"类比推理","module":"判断推理","stem":"<p>有研究发现，儿童受试者考夫曼简明智力测验得分下降与其居住地点黑碳浓度的提高有关。此外，在老年男性群体中，黑碳浓度水平升高1倍，其简易智力状态检查量表（MMSE）得分小于25的OR值为1.3，相当于衰老1.9年。由此，专家认为，黑碳暴露会导致神经系统损伤。<br>以下哪项如果为真，最能削弱上述论证：</p>","options":[{"k":"A","t":"相关研究所关注的儿童和老人群体本身血脑屏障较脆弱，易受黑碳暴露影响"},{"k":"B","t":"颗粒物可以通过嗅球，沿嗅觉神经元传输到大脑，对神经系统产生不良影响"},{"k":"C","t":"最新研究表明，黑碳因其特有的物化属性可能具有比细颗粒物更大的健康影响"},{"k":"D","t":"黑碳暴露与男孩在考夫曼简明智力测验中的反应时间延长和错误率增加有关，而在女孩中未观察到显著相关性"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。</p><p>论点：黑碳暴露会导致神经系统损伤。</p><p>论据：有研究发现，儿童受试者考夫曼简明智力测验得分下降与其居住地点黑碳浓度的提高有关。此外，在老年男性群体中，黑碳浓度水平升高1倍，其简易智力状态检查量表（MMSE）得分小于25的OR值为1.3，相当于衰老1.9年。</p><p>论据说的是“黑碳暴露与智力下降有关”，进而得出论点“黑碳暴露会导致神经系统损伤”，话题一致，削弱优先考虑削弱论点。</p><p>第二步：逐一分析选项。</p><p>A项：该项指出论据中的儿童和老人群体的血脑屏障较为脆弱，易受黑碳暴露影响，解释了为什么这些人容易受到黑碳暴露的影响，具有加强作用，无法削弱，排除；</p><p>B项：指出颗粒物可以通过嗅球，沿嗅觉神经元传输到大脑，对神经系统产生不良影响，黑碳属于颗粒物，解释了黑碳暴露会导致神经系统损伤的原因，属于加强项，无法削弱，排除；</p><p>C项：指出黑碳因其特有的物化属性可能具有比细颗粒物更大的健康影响，但不知道是什么样的影响，不明确是否会导致神经系统损伤，无法削弱，排除；</p><p>D项：指出黑碳暴露与男孩在考夫曼简明智力测验中的反应时间延长和错误率增加有关，而在女孩中未观察到显著相关性，补充女孩的反例，说明该结论不具有普遍性，削弱论点，当选。</p><p>故正确答案为D。</p><p>备注：以下为已查询到的原文，D项在原文中明确作为例证出现，供大家参考。</p><p><img src=\"assets/img/timu/196387ef6aaa735.png\" class=\"fig\" style=\"width:643px;height:380px;\"></p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":70,"pid":"p52147c311e"},{"qid":"13504512","no":29,"type":"类比推理","module":"判断推理","stem":"<p>某研究指出，阻力训练可以帮助预防或延缓阿尔茨海默病（AD）。研究者给小鼠的尾部绑上拉力带，将其放置在一个倾斜的木板上并训练向上爬，训练四周后，小鼠的血液样本分析表明，参与阻力训练小鼠的大脑中很少出现<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白累积，皮质酮（相当于人类分泌的皮质醇）也处于正常水平。除此之外，阻力训练增加了小鼠大脑中小胶质细胞的数量，这种细胞在AD早期对大脑有重要保护作用，比如清除<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白的多肽和细胞碎片，减轻大脑局部炎症。</p><p>以上论述如果为真，必须基于的前提是：</p>","options":[{"k":"A","t":"<p>皮质醇水平在AD早期阶段会呈现升高的趋势</p>"},{"k":"B","t":"<p>大脑中累积的<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白是导致罹患AD的元凶</p>"},{"k":"C","t":"<p>阻力训练会使小胶质细胞从促炎状态转变成抗炎症状态</p>"},{"k":"D","t":"<p>皮质醇会在压力过大时生成并使得个体容易焦虑和躁动</p>"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。</p><p>论点：阻力训练可以帮助预防或延缓阿尔茨海默病。</p><p>论据：研究者给小鼠的尾部绑上拉力带，将其放置在一个倾斜的木板上并训练向上爬，训练四周后，小鼠的血液样本分析表明，参与阻力训练小鼠的大脑中很少出现<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白累积，皮质酮（相当于人类分泌的皮质醇）也处于正常水平。除此之外，阻力训练增加了小鼠大脑中小胶质细胞的数量，这种细胞在AD早期对大脑有重要保护作用。</p><p>本题论点讨论的是阻力训练可以帮助预防或延缓阿尔茨海默病（AD），论据讨论的是阻力训练可以减少<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白累积、使皮质醇处于正常水平；同时阻力训练也可以增加小胶质细胞的数量，从而保护早期AD患者的大脑。其中，论据中的“减少<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白累积、使皮质醇处于正常水平”与论点中的“帮助预防或延缓阿尔茨海默病（AD）”话题不一致，且提问方式为“前提”，优先考虑搭桥，即建立“减少<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白累积、使皮质醇处于正常水平”与“帮助预防或延缓阿尔茨海默病（AD）”的联系。</p><p>第二步：逐一分析选项。</p><p>A项：指出皮质醇水平在AD早期阶段会呈现升高的趋势，但不明确使皮质醇处于正常水平是否有助于预防或延缓阿尔茨海默病，为不明确项，无法加强，排除；</p><p>B项：指出<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白积累会导致罹患AD，说明<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白是AD的病因，即减少<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白有助于预防罹患AD，在“减少<img src=\"assets/img/gongshi/formula-2cef1fcdc275c923.png\" class=\"tex\">-淀粉样蛋白累积”与“帮助预防或延缓阿尔茨海默病”之间建立联系，为搭桥项，是论述成立的前提，当选；</p><p>C项：指出阻力训练会使小胶质细胞从促炎状态转变成抗炎症状态，而减少炎症在AD早期对大脑有保护作用，解释了阻力训练有可能帮助预防或延缓阿尔茨海默病，补充论据，但并非论述成立的前提，排除；</p><p>D项：指出皮质醇会在压力过大时生成并使得个体容易“焦虑和躁动”，与论点讨论的“阿尔茨海默病”无关，为无关项，无法加强，排除。</p><p>故正确答案为B。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":71,"pid":"p52147c311e"},{"qid":"13504447","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>与人类的眼球是一整个球形不同，鸟类眼球是由一大一小的两个半球构成，小的半球是角膜，大的半球是视网膜，在角膜周围有一圈小骨片形成的一个环状的支撑性的脊，这个骨片环即巩膜环，保护眼球的同时也限制了眼球的转动，人类在走路时，通过眼球的转动抵消走路时的振动来保持视觉的稳定，而鸟类无法大幅度地转动眼球。因此，很多鸟类走路时，让头部先移至前方保持稳定，身体再前进。保持不动的头部像是向后缩了一样，于是就成了脖子一伸一缩的样子。<br>由此可以推出：</p>","options":[{"k":"A","t":"鸟类的眼球构造有助于形成更锐利的远视力"},{"k":"B","t":"鸟类走路时脖子的伸缩有助于维持身体的平衡"},{"k":"C","t":"鸟类通过颈部运动让眼睛成像保持更持久的稳定"},{"k":"D","t":"鸟类通过运动头部来获得视差以增强空间的深度感知"}],"answer":"C","multi":false,"explanation":"<p>日常结论题，根据题干信息逐一分析选项。<br>A项：题干中第一句介绍了鸟类的眼球构造，但没有提及此眼球构造有助于形成更锐利的远视力，无中生有，排除；<br>B项：题干中指出鸟类走路时脖子的伸缩有助于保持视觉的稳定，但没有提及有助于维持身体的平衡，无中生有，排除；<br>C项：题干中指出鸟类无法大幅度地转动眼球来保持视觉的稳定。因此，鸟类走路时，让头部先移至前方保持稳定，身体再前进，出现脖子一伸一缩的样子，可以推出鸟类是通过颈部运动让眼睛成像保持更持久的稳定，当选；<br>D项：题干中指出鸟类通过运动头部来保持视觉的稳定，但没有提及通过运动头部来获得视差以增强空间的深度感知，无中生有，排除。<br>故正确答案为C。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":72,"pid":"p52147c311e"},{"qid":"12881901","no":31,"type":"逻辑判断","module":"判断推理","stem":"<p>某地湖水水位的季节性变化显著，洪水期和枯水期的湖水面积和蓄水量相差悬殊，每到秋冬季节进入枯水期，湖水水位急剧下降，湖面沙洲裸露，仅剩几条蜿蜒的水道，对当地居民的生产生活造成不良影响。当地政府计划在湖泊口建设一道巨型水闸，可以在秋冬季节蓄住湖水，以满足灌溉、航运、生活等需求。生态专家认为，水闸不会对生态环境造成负面影响，甚至能够优化当地物种的生存环境。<br>以下哪项如果为真，最能削弱上述论证：</p>","options":[{"k":"A","t":"该湖泊是某些候鸟的栖息地，每年都会吸引它们来此越冬"},{"k":"B","t":"蓄水会导致湖泊的冬季水位上涨，某些种类的候鸟喜爱浮水游动"},{"k":"C","t":"水闸上会预留数个60米宽的洄游通道，供江豚等水生动物洄游觅食"},{"k":"D","t":"湖泊周围主要的鸟类种群以水生植物块茎和底栖生物为食，需要栖息在较浅的水陆交错环境"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：水闸不会对生态环境造成负面影响，甚至能够优化当地物种的生存环境。<br>论据：无。<br>本题只有论点，没有论据，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项指出该湖泊是某些候鸟的栖息地，每年都会吸引它们来此越冬，而论点讨论的是水闸对生态环境、当地物种的影响，话题不一致，无法削弱，排除；<br>B项：该项指出蓄水会导致湖泊的冬季水位上涨，某些种类的候鸟喜爱浮水游动，说明水闸建设优化了候鸟的生存环境，为加强项，无法削弱，排除；<br>C项：该项指出水闸上会预留数个60米宽的洄游通道，供江豚等水生动物洄游觅食，说明水闸建设不会影响江豚等水生动物的生存环境，不会对生态环境造成负面影响，为加强项，无法削弱，排除；<br>D项：该项指出湖泊周围主要的鸟类种群需要栖息在较浅的水陆交错环境，说明水闸建设带来的高蓄水量不利于鸟类种群的栖息，削弱论点，可以削弱，当选。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":73,"pid":"p52147c311e"},{"qid":"13504503","no":32,"type":"逻辑判断","module":"判断推理","stem":"<p>大蚕蛾具有其他昆虫无法比拟的巨大翅膀，长度可达28cm，是自然界中最为绚丽灿烂的昆虫之一。在自然界中，为了吸引异性，许多动物都拥有鲜艳美丽的外形，因此，科学家认为，大蚕蛾的“锦衣华服”是用于吸引异性，从而增加交配繁殖的几率。<br>以下哪项如果为真，最能削弱上述结论：</p>","options":[{"k":"A","t":"绝大部分种类的大蚕蛾生存繁衍于群山密林之中，昼伏夜出，无法看清同类的翅膀"},{"k":"B","t":"大蚕蛾翅膀的绚丽来自于鳞片的密集排布，能折射和衍射光线，从而让天敌分心或疑惑"},{"k":"C","t":"大蚕蛾头顶的触角是重要的感觉器官，主要起到嗅觉和触觉作用，可以通过触角进行信息交流"},{"k":"D","t":"大蚕蛾雌雄两性的色泽不同，雄性大体呈橘黄色，翅膀以杏黄色为主，雌性为青白色，翅膀以淡绿色为主"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：大蚕蛾的“锦衣华服”是用于吸引异性，从而增加交配繁殖的几率。<br>论据：在自然界中，为了吸引异性，许多动物都拥有鲜艳美丽的外形。<br>本题论点和论据均在讨论“外形”和“吸引异性”的关系，二者话题一致，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：该项指出绝大部分种类的大蚕蛾生存繁衍于群山密林，无法看清同类的翅膀，说明大蚕蛾无法依靠外形吸引异性，增加交配繁殖的几率，削弱论点，可以削弱，当选；<br>B项：该项指出大蚕蛾翅膀绚丽的原因，绚丽的翅膀能让天敌分心或疑惑，但并未提及绚丽翅膀能否吸引异性，增加交配繁殖的几率，话题不一致，无法削弱，排除；<br>C项：该项指出大蚕蛾头顶的触角能起到哪些作用，而论点讨论的是大蚕蛾的绚丽翅膀能否吸引异性，增加交配繁殖的几率，话题不一致，无法削弱，排除；<br>D项：该项指出大蚕蛾雌雄两性的色泽区别，而论点讨论的是大蚕蛾的绚丽翅膀能否吸引异性，增加交配繁殖的几率，话题不一致，无法削弱，排除。<br>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":74,"pid":"p52147c311e"},{"qid":"12881902","no":33,"type":"逻辑判断","module":"判断推理","stem":"<p>人类的饮食需在更具营养的同时减少对气候的影响。因此，未来饮食策略应思考降低温室气体的排放，多考虑基于海产的“蓝色”饮食。海产品是良好的蛋白、脂肪酸、维生素和矿物质来源，其中有一半营养密度高于牛肉、猪肉和鸡肉。专家通过资料分析了全球野外捕捞和养殖的海产品营养密度及其对气候的影响发现，野外捕捞鲑鱼、鲱鱼及养殖贻贝、牡蛎等海产品温室气体排放量较低，对气候的影响也小。因此，可持续的海产品消费能够在为人类提供更多营养的同时减轻环境压力。<br>由此可以推出：</p>","options":[{"k":"A","t":"为进一步降低碳排放，渔业应采用节能高效的捕捞技术"},{"k":"B","t":"未来，人们在饮食策略中将大量采用海产品替代其他肉类"},{"k":"C","t":"每一物种的生产或捕获方法的差异，会给气候变化带来很大不同"},{"k":"D","t":"鼓励以海产的“蓝色”饮食替代其他动物蛋白，或可帮助应对气候变化"}],"answer":"D","multi":false,"explanation":"<p>日常结论题，根据题干信息逐一分析选项。<br>A项：题干并未提及应采用哪种捕捞技术，无中生有，无法推出，排除；<br>B项：题干仅指出未来应“多考虑”基于海产的“蓝色”饮食，但这不意味着人们在饮食策略中将“大量采用”海产品替代其他肉类，建议不代表一定会发生，且表述过于绝对，无法推出，排除；<br>C项：题干仅针对野外捕捞鲑鱼、鲱鱼及养殖贻贝、牡蛎等部分海产品进行了温室气体排放量以及对气候影响的分析，并未提及“每一物种”的生产或捕获方法差异对气候变化有“很大不同”，范围扩大，且表述过于绝对，无法推出，排除；<br>D项：题干第二句指出降低温室气体排放应多考虑基于海产的“蓝色”饮食，题干的第四句指出部分海产品温室气体排放量较低，最后一句指出可持续的海产品消费能够减轻环境压力，说明鼓励以基于海产的“蓝色”饮食代替其他动物蛋白，可能能够帮助应对气候变化，可以推出，当选。<br>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":75,"pid":"p52147c311e"},{"qid":"13504432","no":34,"type":"类比推理","module":"判断推理","stem":"<p>某市举办智能数控技能大赛，小周、小吴、小郑、小王、小钱进入了决赛。比赛后，有记者询问他们的感受，他们回答如下：<br>小周：小郑整场发挥得都很好，我觉得冠军非他莫属；<br>小吴：我觉得冠军一定会在我、小周、小钱三人之中产生；<br>小郑：我自我感觉不好，这次与冠军无缘了；<br>小钱：我连季军都拿不到；<br>小王：我不会是亚军。<br>已知本次比赛产生了冠军、亚军、季军各一人，且在五人中只有一个人的回答与比赛结果相符。那么，获得亚军的是：</p>","options":[{"k":"A","t":"小王"},{"k":"B","t":"小吴"},{"k":"C","t":"小郑"},{"k":"D","t":"小钱"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出题干矛盾命题。</p><p>小周：小郑冠军；</p><p>小吴：小吴冠军 或 小周冠军 或 小钱冠军；</p><p>小郑：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">小郑冠军；</p><p>小钱：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">小钱前三；</p><p>小王：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">小王亚军。</p><p>分析题干条件可知，小周和小郑说的话为矛盾关系，必有一真一假。</p><p>第二步：根据题干条件推理。</p><p>根据题干条件可知，只有一个人的回答为真，则回答为真的人一定在小周和小郑之间，小吴、小钱和小王的回答均为假。小王说自己不是亚军为假，则小王是亚军，对应A项。</p><p>故正确答案为A。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":76,"pid":"p52147c311e"},{"qid":"13504446","no":35,"type":"逻辑判断","module":"判断推理","stem":"<p>某公园计划从桃树、李树、杨树、柳树、松树中选择几种树种植，树种的选择满足下列条件：<br>（1）如果选桃树，那么不选松树； <br>（2）要么选桃树，要么选李树；<br>（3）至少选3种树种植；<br>（4）桃树和杨树至多选1种；<br>（5）李树和柳树至多选1种。<br>由此可以推出：</p>","options":[{"k":"A","t":"种李树和桃树，不种松树"},{"k":"B","t":"种桃树和柳树，不种杨树"},{"k":"C","t":"种李树和杨树，不种松树"},{"k":"D","t":"种杨树和松树，不种桃树"}],"answer":"D","multi":false,"explanation":"<p>第一步：分析题干条件。</p><p>（1）桃树<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">松树；</p><p>（2）要么选桃树，要么选李树；</p><p>（3）至少选3种树种植；</p><p>（4）<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">桃树 或 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">杨树；</p><p>（5）<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">李树 或 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">柳树。</p><p>第二步：根据题干条件进行推理。</p><p>题干条件中“桃树”提及次数最多，可优先从此处入手进行推理。</p><p>若种桃树，结合条件（1）（2）（4）可得，不能种松树、李树和杨树，结合题干信息共有“桃树、李树、杨树、柳树、松树”这5种树，则此时只能种桃树和柳树这两种树，与条件（3）矛盾，故不能种桃树。</p><p>不种桃树，结合条件（2）可得，要种植李树；结合条件（5）否一推一可得，不种柳树。结合题干信息共有“桃树、李树、杨树、柳树、松树”这5种树，根据上述结论“不种桃树”和“不种柳树”，结合条件（3）可得，种李树、杨树和松树，只有D项说法完全正确。</p><p>故正确答案为D。</p>","from":{"file":"2025年湖北省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":77,"pid":"p52147c311e"}]};
